window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[188]={"id":"188","numero":188,"titre":"Asthme, rhinite — Hypersensibilité et allergies respiratoires","objectifs":[{"id":"188-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’asthme et de la rhinite allergique (chez l’adulte et l’enfant, selon l’âge chez l’enfant)","contenu":"<p L'<strong><span class=\"kw-def\">asthme</span></strong> est une <strong>maladie inflammatoire chronique</strong> des voies aériennes inférieures qui associe :</p>\n      <ul>\n        <li><strong>Symptômes respiratoires variables</strong> — <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">sifflements</span>, <span class=\"kw-clinique\">oppression thoracique</span>, <span class=\"kw-clinique\">toux</span> ;</li>\n        <li><strong>Obstruction des voies aériennes</strong> — variable dans le temps et/ou réversible totalement ou partiellement sous <span class=\"kw-ttt\">bronchodilatateurs d'action rapide</span>.</li>\n      </ul>\n      <h4>Terminologie des épisodes aigus</h4>\n      <table>\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><th>Symptômes d'asthme</th><td>Gêne respiratoire, dyspnée, sifflements, toux — <strong>durée brève</strong> (<span class=\"kw-chiffre\">&lt; 20 min</span>), variables, réversibles</td></tr>\n          <tr><th><span class=\"kw-def\">Exacerbation</span></th><td>Augmentation progressive des symptômes durant <span class=\"kw-chiffre\">≥ 2 jours</span>, nécessitant une modification du traitement, non calmée par les BDCA, sans retour à l'état habituel</td></tr>\n        </tbody>\n      </table>\n      <h4>Définition pédiatrique — enfant préscolaire (&lt; 5 ans)</h4>\n      <p>Définition arbitraire mais consensuelle : répétition de <strong><span class=\"kw-chiffre\">≥ 3 épisodes dyspnéiques avec sifflements</span></strong> avant l'âge de <span class=\"kw-chiffre\">&lt; 3 ans</span>.</p>\n      <h4>Rhinite allergique</h4>\n      <p>Expression clinique d'une <span class=\"kw-clinique\">rhinite</span> associée à un constat immuno-allergique (<strong>inflammation IgE-dépendante</strong>), souvent associée à un <span class=\"kw-clinique\">asthme</span>, une <span class=\"kw-clinique\">conjonctivite</span>, et à des infections des voies aériennes supérieures.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Asthme = inflammation + obstruction bronchique variable et réversible. Rhinite allergique = inflammation IgE-dépendante de la muqueuse nasale. Les deux appartiennent au continuum <em>« une seule voie aérienne, une seule maladie »</em>.\n      </div>","frequence":0},{"id":"188-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence et les facteurs de risque de l’asthme et de la rhinite allergique dans la population adulte et pédiatrique","contenu":"<table>\n        <thead><tr><th>Population</th><th>Prévalence</th></tr></thead>\n        <tbody>\n          <tr><th>Adulte (France)</th><td>Asthme <span class=\"kw-chiffre\">6 %</span> · Rhinite allergique <span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><th>Enfant d'âge scolaire</th><td>Asthme <span class=\"kw-chiffre\">10-11 %</span> → <strong>1<sup>re</sup> maladie chronique de l'enfant</strong></td></tr>\n          <tr><th>Enfant préscolaire (0-5 ans)</th><td>Prévalence encore <strong>plus élevée</strong></td></tr>\n          <tr><th>Asthmatiques</th><td><span class=\"kw-chiffre\">80 %</span> ont une rhinite allergique associée</td></tr>\n        </tbody>\n      </table>\n      <h4>Facteurs de persistance après l'adolescence</h4>\n      <ul>\n        <li>Sexe <strong>féminin</strong> ;</li>\n        <li><span class=\"kw-etio\">Tabagisme actif</span> précoce ;</li>\n        <li><span class=\"kw-def\">Hyperréactivité bronchique</span>.</li>\n      </ul>\n      <h4>Coûts et mortalité</h4>\n      <table>\n        <thead><tr><th>Indicateur</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><th>Coût total France</th><td><span class=\"kw-chiffre\">1,5 Md€/an</span> — directs <span class=\"kw-chiffre\">65 %</span> (hôpital, tt, consult.) · indirects <span class=\"kw-chiffre\">35 %</span> (absentéisme)</td></tr>\n          <tr><th>Mortalité</th><td>~<span class=\"kw-chiffre\">1000 décès/an</span> (adulte) · <span class=\"kw-chiffre\">10-15 décès/an</span> (enfant)</td></tr>\n          <tr><th>Facteurs de mortalité évitable</th><td>Absence ou mauvaise observance du <span class=\"kw-ttt\">traitement de fond</span> ; mauvaise gestion de la crise ; recours médical trop tardif ; niveau socio-économique défavorisé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> La <span class=\"kw-alerte\">mortalité par asthme reste trop importante</span> et largement <span class=\"kw-alerte\">évitable</span> chez le sujet jeune — d'où l'enjeu de l'observance du traitement de fond et du plan d'action écrit.\n      </div>","frequence":0},{"id":"188-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie et immunopathologie de l’asthme et de la rhinite allergique","contenu":"<h4>Génétique</h4>\n      <p>Maladie <strong>polygénique</strong> — aucun gène n'est responsable à lui seul.</p>\n      <ul>\n        <li>Aucun ATCD parental : risque enfant <span class=\"kw-chiffre\">10 %</span> ;</li>\n        <li>1 parent asthmatique : <span class=\"kw-chiffre\">25 %</span> ;</li>\n        <li>2 parents asthmatiques : <span class=\"kw-chiffre\">&gt; 50 %</span>.</li>\n      </ul>\n      <h4>Facteurs environnementaux</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Infections virales</span> — déclencheur + facteur d'hyperréactivité bronchique durable (nourrisson ++) ;</li>\n        <li>Sensibilisation aux <span class=\"kw-etio\">pneumallergènes</span> (acariens, animaux domestiques, pollens) ;</li>\n        <li><span class=\"kw-etio\">Tabac</span> dès la conception (tabagisme parental) ;</li>\n        <li><span class=\"kw-etio\">Pollution</span> intérieure et atmosphérique ;</li>\n        <li>Altération du microbiote néonatal ;</li>\n        <li><span class=\"kw-etio\">Exercice</span> — bronchospasme chez <span class=\"kw-chiffre\">&gt; 80 %</span> des enfants asthmatiques (air froid et sec).</li>\n      </ul>\n      <h4>Les 3 mécanismes physiopathologiques</h4>\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><th>Inflammation bronchique chronique</th><td><strong>Asthme T2</strong> (allergique ou éosinophilique) : cytokines Th2 (<span class=\"kw-bio\">IL-4</span>, <span class=\"kw-bio\">IL-5</span>, <span class=\"kw-bio\">IL-13</span>) → commutation isotypique LB → <span class=\"kw-bio\">IgE</span> ; rôle des <span class=\"kw-bio\">lymphocytes Th2</span> et des <span class=\"kw-bio\">éosinophiles</span><br><strong>Asthme non-T2</strong> : inflammation indépendante des Th2/éosinophiles ; rôle possible des <span class=\"kw-bio\">PNN</span></td></tr>\n          <tr><th><span class=\"kw-def\">Hyperréactivité bronchique</span></th><td>Bronchoconstriction exagérée à divers stimuli : air froid, méthacholine, allergènes, agents professionnels</td></tr>\n          <tr><th>Remodelage bronchique</th><td>Anomalies épithélium bronchique ; épaississement de la <strong>membrane basale</strong> ; hyperperméabilité vasculaire → œdème ; hyperplasie/hypertrophie des <strong>cellules musculaires lisses</strong> ; hypersécrétion de mucus → <strong>obstruction bronchique</strong> par épaississement + obstruction luminale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Continuum allergique.</strong> Même patrimoine génétique + environnement différent → rhinite <em>ou</em> asthme. Le remodelage bronchique est associé à la chronicité et <strong>n'est pas spécifique du caractère allergique</strong>.\n      </div>","frequence":1},{"id":"188-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’une rhinite allergique chez l’enfant et l’adulte","contenu":"<h4>Classification ARIA</h4>\n      <table>\n        <thead><tr><th>Durée</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><th>Intermittente</th><td><span class=\"kw-chiffre\">≤ 4 semaines consécutives/an</span> <strong>ou</strong> <span class=\"kw-chiffre\">&lt; 4 jours/semaine</span></td></tr>\n          <tr><th>Persistante</th><td><span class=\"kw-chiffre\">&gt; 4 semaines consécutives/an</span> <strong>ou</strong> <span class=\"kw-chiffre\">&gt; 4 jours/semaine</span></td></tr>\n        </tbody>\n      </table>\n      <table>\n        <thead><tr><th>Gravité</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><th>Légère</th><td>Sommeil normal ; activités sociales/sportives normales ; scolaire/pro normal ; symptômes peu gênants</td></tr>\n          <tr><th>Sévère (<span class=\"kw-chiffre\">≥ 1</span>)</th><td><span class=\"kw-alerte\">Sommeil perturbé</span> ; activités sociales/sportives perturbées ; scolaire/pro perturbé ; symptômes gênants</td></tr>\n        </tbody>\n      </table>\n      <h4>Diagnostic clinique — moyen mnémotechnique <span class=\"kw-def\">APERO</span></h4>\n      <ul>\n        <li><strong>A</strong>nosmie ;</li>\n        <li><strong>P</strong>rurit nasal, palais, parfois CAE ;</li>\n        <li><strong>É</strong>ternuements répétés en salves ;</li>\n        <li><strong>R</strong>hinorrhée claire, jetage postérieur ;</li>\n        <li><strong>O</strong>bstruction nasale bilatérale (alterne avec la rhinorrhée).</li>\n      </ul>\n      <p>Associés : <span class=\"kw-clinique\">conjonctivite</span> dans <span class=\"kw-chiffre\">80 %</span> des cas ; muqueuses nasales pâles/œdématiées ou inflammatoires ; rechercher des <strong>polypes</strong> si évolution prolongée.</p>\n      <h4>Confirmation immuno-allergologique — indispensable</h4>\n      <ol>\n        <li><strong>Prick-tests</strong> orientés par l'interrogatoire — <span class=\"kw-chiffre\">1<sup>re</sup> intention</span> ;</li>\n        <li>Dosage d'<span class=\"kw-bio\">IgE spécifiques</span> si prick-tests négatifs.</li>\n      </ol>\n      <p><span class=\"kw-ci\">Pas de bilan radiologique</span> sauf recherche de diagnostic différentiel/associé.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Drapeaux rouges — ce n'est PAS une rhinite allergique.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Rhinite initialement claire devenant mucopurulente</span> → origine infectieuse ou déficit immunitaire ;</li>\n          <li><span class=\"kw-alerte\">Douleur ou saignement</span> → éliminer processus néoplasique, maladie inflammatoire chronique, vascularite (Wegener) ;</li>\n          <li>Obstruction unilatérale, épistaxis, adénopathie → imagerie + ORL.</li>\n        </ul>\n      </div>\n      <h4>Focus — Syndrome d'allergie pollen-aliment (SAPA)</h4>\n      <p>Allergie croisée entre protéines de pollens et protéines alimentaires (ex : Bet v 1 du bouleau ↔ Mal d 1 de la pomme, famille PR-10). Syndrome oral : prurit oropharyngé, œdème labial <strong>dès la mise en bouche</strong> du fruit/légume cru. Aliment cuit toléré (protéines thermolabiles).</p>","frequence":2},{"id":"188-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","contenu":"<div class=\"callout callout-info\">\n        <strong>Équation diagnostique.</strong> Diagnostic positif = <span class=\"kw-clinique\">symptômes caractéristiques</span> + <span class=\"kw-bio\">TVO réversible</span> aux EFR (totalement ou partiellement, à l'état basal ou après test de provocation). Un TVO réversible <strong>seul ne suffit pas</strong> — il doit être associé à des symptômes.\n      </div>\n      <h4>Histoire clinique caractéristique</h4>\n      <table>\n        <thead><tr><th>Item</th><th>Recueil</th></tr></thead>\n        <tbody>\n          <tr><th>Terrain</th><td><strong>Atopie</strong> personnelle/familiale du 1<sup>er</sup> degré : rhinoconjonctivite, asthme allergique, dermatite atopique, allergie alimentaire</td></tr>\n          <tr><th>Symptômes fonctionnels</th><td><ul><li><span class=\"kw-clinique\">Dyspnée expiratoire</span> avec sifflements</li><li><span class=\"kw-clinique\">Oppression thoracique</span></li><li><span class=\"kw-clinique\">Toux</span> non productive intercritique</li><li>Réduction d'activité chez l'enfant (fatigue précoce, veut être porté)</li></ul>Arguments forts : <strong>plusieurs symptômes associés, variables, réversibles, brefs (<span class=\"kw-chiffre\">&lt; 20 min</span>)</strong></td></tr>\n          <tr><th>Horaire</th><td>Aggravation <strong>nocturne</strong> ou au <strong>petit matin</strong> (nadir du cortisol endogène)</td></tr>\n          <tr><th>Facteurs déclenchants</th><td><ul><li><span class=\"kw-etio\">Infections virales</span></li><li><span class=\"kw-etio\">Exercice</span> (dyspnée quelques minutes <strong>après</strong> l'effort)</li><li>Équivalents : rire, pleurs, air froid</li><li><span class=\"kw-etio\">Allergènes</span> et irritants (tabac passif, pollution)</li></ul></td></tr>\n          <tr><th>Signes physiques</th><td>Auscultation normale en intercritique ; <strong><span class=\"kw-clinique\">sibilants bilatéraux</span></strong> à l'expiration forcée pendant la crise ; wheezing récurrent chez l'enfant</td></tr>\n          <tr><th>Épreuve thérapeutique</th><td><span class=\"kw-ttt\">CSI</span> pendant <span class=\"kw-chiffre\">2-3 mois</span> → amélioration + reprise des signes à l'arrêt = argument fort (pédiatrie)</td></tr>\n        </tbody>\n      </table>\n      <h4>Mise en évidence de l'obstruction bronchique variable et réversible</h4>\n      <table>\n        <thead><tr><th>Critère</th><th>Adulte</th><th>Enfant</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-bio\">TVO</span></th><td><span class=\"kw-chiffre\">VEMS/CVF &lt; 0,7</span></td><td><span class=\"kw-chiffre\">VEMS/CVF &lt; 0,8</span> (normal <span class=\"kw-chiffre\">&gt; 0,9</span>)</td></tr>\n          <tr><th>Réversibilité <strong>partielle</strong> post-BDCA</th><td>↑ VEMS <span class=\"kw-chiffre\">≥ 200 mL</span> <strong>ET</strong> <span class=\"kw-chiffre\">≥ 12 %</span></td><td>↑ VEMS <span class=\"kw-chiffre\">≥ 12 %</span> et <span class=\"kw-chiffre\">≥ 200 mL</span></td></tr>\n          <tr><th>Réversibilité <strong>complète</strong></th><td>VEMS/CVF post <span class=\"kw-chiffre\">&gt; 0,7</span> <strong>ET</strong> VEMS post <span class=\"kw-chiffre\">&gt; 80 %</span> prédite</td><td>—</td></tr>\n          <tr><th>Test à la <span class=\"kw-ttt\">méthacholine</span></th><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span> = HRB</td><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span></td></tr>\n          <tr><th>Provocation à l'effort</th><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span></td><td>↓ VEMS <span class=\"kw-chiffre\">≥ 12 %</span></td></tr>\n        </tbody>\n      </table>\n      <h4>CAT selon spirométrie</h4>\n      <ul>\n        <li><strong>Spirométrie normale</strong> — n'élimine pas l'asthme : la répéter ou rechercher une HRB (méthacholine, effort) ;</li>\n        <li><strong>TVO réversible + symptômes</strong> → diagnostic confirmé ;</li>\n        <li><strong>TVO non réversible + forte suspicion</strong> → refaire spirométrie après CTC systémique <span class=\"kw-chiffre\">2 sem</span> ou CSI <span class=\"kw-chiffre\">4-6 sem</span>.</li>\n      </ul>\n      <h4>Diagnostics différentiels</h4>\n      <table>\n        <thead><tr><th>Adulte — sans TVO ni HRB</th><th>Adulte — TVO non réversible</th></tr></thead>\n        <tbody>\n          <tr><td><ul><li>Dysfonction des cordes vocales</li><li>Syndrome d'hyperventilation</li></ul></td><td><ul><li><span class=\"kw-def\">BPCO</span></li><li>Bronchectasies (DDB)</li><li>Mucoviscidose</li><li>Bronchiolites constrictives</li><li>Corps étranger inhalé</li><li>Tumeur trachéo-bronchique</li><li>Insuffisance cardiaque</li></ul></td></tr>\n        </tbody>\n      </table>\n      <table>\n        <thead><tr><th>Enfant — orientation vers autre diagnostic 🚩</th></tr></thead>\n        <tbody>\n          <tr><td><ul><li><strong>Obstruction VA proximales :</strong> malacie, sténose, corps étranger, compressions (arcs aortiques, kyste bronchogénique, tumeur, ADP tuberculeuse)</li><li><strong>Petites VA :</strong> mucoviscidose, dysplasie bronchopulmonaire, dyskinésie ciliaire, bronchiolite oblitérante</li><li><strong>Pathologie d'inhalation :</strong> RGO, fistule œsotrachéale, troubles de déglutition</li><li><strong>Cardiopathie congénitale :</strong> shunt G-D, cardiomégalie</li><li><strong>Immunodépression :</strong> infections opportunistes</li></ul></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Signes d'alerte pédiatriques 🚩</strong> — début &lt; 1 mois de vie, absence d'intervalle libre, wheezing continu, stridor, dyspnée aux 2 temps, hippocratisme digital, ralentissement staturo-pondéral, diarrhée chronique, fausses routes, infections ORL bactériennes fréquentes, échec des mesures thérapeutiques bien conduites, anomalie de la <span class=\"kw-imagerie\">RXT</span>.\n      </div>","frequence":10},{"id":"188-6","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier le caractère professionnel d’une allergie respiratoire : démarche diagnostique étiologique","contenu":"<div class=\"callout callout-info\">\n        <strong>Chiffres clés.</strong> Asthme professionnel = <span class=\"kw-chiffre\">10-15 %</span> des asthmes de l'adulte → <strong>MROP la plus fréquente</strong> dans les pays industriels. Délai de PEC (délai maximal entre fin de l'exposition et 1<sup>re</sup> constatation médicale) = <span class=\"kw-chiffre\">7 jours</span>.\n      </div>\n      <h4>Distinction fondamentale</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><th>Asthme préexistant <em>aggravé</em> par le travail</th><td><span class=\"kw-alerte\">≠ asthme professionnel</span> — à distinguer</td></tr>\n          <tr><th>Asthme professionnel <strong>avec</strong> période de latence</th><td>Mécanisme <strong>immunologique</strong> ; latence = temps de sensibilisation. Deux voies : IgE-dépendante (haut PM et quelques bas PM) ; mécanisme IgE non démontré (isocyanates, acrylates…)</td></tr>\n          <tr><th>Asthme <strong>sans</strong> période de latence — Syndrome de Brooks</th><td>Mécanisme non immunologique ; exposition accidentelle unique à un irritant respiratoire (vapeur, gaz, fumée) ou à faibles doses répétées</td></tr>\n        </tbody>\n      </table>\n      <h4>Démarche diagnostique en 3 étapes</h4>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th>1. Affirmer l'asthme</th><td><span class=\"kw-bio\">EFR</span> : TVO réversible ou HRB à la méthacholine (chute VEMS <span class=\"kw-chiffre\">&gt; 20 %</span>)</td></tr>\n          <tr><th>2. Affirmer l'origine professionnelle</th><td><ul><li>Interrogatoire : profession à risque, rythme professionnel, produits manipulés</li><li>Amélioration pendant les <strong>congés</strong>, aggravation en période de travail</li><li>Automesures pluriquotidiennes de <span class=\"kw-def\">DEP</span> et/ou <span class=\"kw-bio\">VEMS</span> avec journal</li><li>Présence d'une <span class=\"kw-bio\">HRBNS</span> en période de travail vs hors travail (milieu pneumologique)</li></ul></td></tr>\n          <tr><th>3. Identifier l'agent</th><td><ul><li><strong>Prick-tests</strong> orientés (milieu allergologique)</li><li>Dosage d'<span class=\"kw-bio\">IgE spécifiques</span> (utile surtout pour agents de haut PM)</li><li>Pneumallergènes courants (Phadiatop)</li><li>Test de provocation bronchique spécifique (milieu hospitalier, VEMS <span class=\"kw-chiffre\">&gt; 70 %</span>, sans HRBNS)</li><li>Test de provocation nasale si symptômes ORL</li></ul></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une enquête étiologique <strong>négative n'élimine pas</strong> l'origine professionnelle. L'apparition d'une <span class=\"kw-clinique\">rhinite allergique</span> professionnelle est un <span class=\"kw-alerte\">signe d'alarme</span> d'un asthme professionnel à venir.\n      </div>","frequence":5},{"id":"188-7","rang":"B","rubrique":"Étiologies","titre":"Connaître les principaux métiers à risque d’asthme professionnel","contenu":"<p>Ces <strong>6 métiers</strong> se partagent <span class=\"kw-chiffre\">50 %</span> des asthmes professionnels déclarés :</p>\n      <table>\n        <thead><tr><th>Métier</th><th>Agents incriminés</th></tr></thead>\n        <tbody>\n          <tr><th>Boulangers-pâtissiers <em>(prédominance ♂)</em></th><td><ul><li>Farines de céréales (<strong>blé</strong>, <strong>seigle</strong>)</li><li>Enzymes améliorants (alpha-amylase, <strong>cellulase</strong>)</li><li>Contaminants (<strong>acariens de stockage</strong>, <strong>blatte</strong>)</li></ul></td></tr>\n          <tr><th>Métiers de la santé <em>(♀, <span class=\"kw-chiffre\">10 %</span> des AP)</em></th><td><ul><li><strong>Latex</strong> (gants)</li><li><strong>Aldéhydes</strong> (para-, glutaraldéhyde) — désinfection, fixation</li><li><strong>Ammoniums quaternaires</strong>, oxyde d'éthylène</li></ul></td></tr>\n          <tr><th>Coiffeurs <em>(♀)</em></th><td><ul><li><strong>Persulfates alcalins</strong> (décoloration)</li><li>Teintures capillaires</li><li>Produits de permanente</li></ul></td></tr>\n          <tr><th>Peintres au pistolet (industrie automobile)</th><td><ul><li><strong>Isocyanates</strong> (peintures polyuréthanes)</li><li>Solvants (aggravants irritatifs)</li></ul></td></tr>\n          <tr><th>Travailleurs du bois</th><td><ul><li>Bois exotiques</li><li>Colles (colophane, formaldéhyde)</li><li>Vernis (isocyanates)</li></ul></td></tr>\n          <tr><th>Métiers de nettoyage</th><td><ul><li>Acariens</li><li>Latex (gants)</li><li>Ammoniums quaternaires</li><li>Amines aliphatiques</li><li>Sprays → pénétration facilitée</li></ul></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"188-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités d’évaluation du contrôle de l’asthme","contenu":"<h4>Contrôle chez l'adulte — questionnaire <span class=\"kw-def\">ACT</span> (Asthma Control Test)</h4>\n      <p>5 items cotés de 1 à 5, sur les <strong>4 dernières semaines</strong> :</p>\n      <ul>\n        <li>Limitation des activités (travail, école, domicile) ;</li>\n        <li>Nombre d'épisodes de dyspnée ;</li>\n        <li>Symptômes nocturnes ou matinaux (sifflement, toux, essoufflement, oppression) ;</li>\n        <li>Utilisation d'un traitement de secours ;</li>\n        <li>Auto-évaluation globale.</li>\n      </ul>\n      <p><strong>Cut-off :</strong> asthme contrôlé si score <span class=\"kw-chiffre\">≥ 20/25</span>.</p>\n      <h4>Critères d'asthme contrôlé (adulte)</h4>\n      <ul>\n        <li>Symptômes contrôlés sur 4 semaines (<span class=\"kw-def\">ACT</span> <span class=\"kw-chiffre\">≥ 20</span>) ;</li>\n        <li>Exacerbations rares : <span class=\"kw-chiffre\">≤ 1</span> cure de CTC systémique/an ;</li>\n        <li>Pas d'obstruction bronchique : VEMS/CVF <span class=\"kw-chiffre\">&gt; 0,7</span> et VEMS <span class=\"kw-chiffre\">≥ 80 %</span>.</li>\n      </ul>\n      <h4>Contrôle chez l'enfant (4 dernières semaines)</h4>\n      <table>\n        <thead><tr><th>Critère de non-contrôle</th><th>0-5 ans</th><th>≥ 6 ans</th></tr></thead>\n        <tbody>\n          <tr><th>Symptômes diurnes</th><td><span class=\"kw-chiffre\">&gt; 1/sem</span></td><td><span class=\"kw-chiffre\">&gt; 2/sem</span></td></tr>\n          <tr><th>Symptômes nocturnes</th><td>≥ 1 réveil ou 1 accès de toux liés à l'asthme</td><td>≥ 1 réveil</td></tr>\n          <tr><th>Bronchodilatateur de secours</th><td><span class=\"kw-chiffre\">&gt; 1/sem</span></td><td><span class=\"kw-chiffre\">&gt; 2/sem</span></td></tr>\n          <tr><th>Activités</th><td colspan=\"2\">Toute limitation liée à l'asthme</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation :</strong> bon contrôle = <strong>0 critère</strong> · contrôle partiel = <strong>1-2</strong> · mauvais contrôle = <strong>3-4</strong>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À rechercher en cas d'asthme non contrôlé.</strong>\n        <ol>\n          <li><strong>Observance</strong> (évaluée à <span class=\"kw-chiffre\">~50 %</span> chez l'enfant) ;</li>\n          <li><strong>Technique</strong> d'inhalation ;</li>\n          <li><strong>Facteurs favorisants persistants</strong> : tabagisme, allergène non éliminé, RGO, obésité, rhinosinusite, SAHOS ;</li>\n          <li><strong>Comorbidités</strong> allergiques et non allergiques ;</li>\n          <li><strong>Posologie</strong> de <span class=\"kw-ttt\">CSI</span> inadaptée ;</li>\n          <li>Éosinophilie sanguine/expectoration.</li>\n        </ol>\n      </div>","frequence":4},{"id":"188-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’exacerbation d’asthme chez l’enfant et l’adulte","contenu":"<p>L'<strong><span class=\"kw-def\">exacerbation</span></strong> est une augmentation progressive des <span class=\"kw-clinique\">symptômes respiratoires</span> durant <span class=\"kw-chiffre\">≥ 2 jours</span>, non calmée par les <span class=\"kw-ttt\">BDCA</span> utilisés fréquemment et en quantité importante, nécessitant une modification du traitement, <strong>sans retour à l'état habituel</strong>.</p>\n      <h4>Différencier crise, exacerbation, asthme aigu grave</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Durée</th><th>Réponse aux BDCA</th></tr></thead>\n        <tbody>\n          <tr><th>Symptôme d'asthme (crise)</th><td><span class=\"kw-chiffre\">&lt; 20 min</span></td><td>Cède spontanément ou aux BDCA</td></tr>\n          <tr><th>Exacerbation</th><td><span class=\"kw-chiffre\">≥ 2 jours</span></td><td>Non calmée par BDCA fréquents</td></tr>\n          <tr><th>Asthme aigu grave (AAG)</th><td>Variable</td><td>≥ 1 <span class=\"kw-alerte\">signe de gravité</span> (cf objectif 10)</td></tr>\n        </tbody>\n      </table>\n      <h4>Évaluation de la sévérité — 4 axes</h4>\n      <ol>\n        <li>Interrogatoire — ancienneté, tt pris, réponse ;</li>\n        <li>Clinique — FR, FC, PA, parole, tirage, cyanose ;</li>\n        <li>Paraclinique — <span class=\"kw-bio\">SpO₂</span>, <span class=\"kw-def\">DEP</span> (adulte, enfant coopérant) ;</li>\n        <li>Terrain — ATCD de séjour en réa, corticothérapie orale récente.</li>\n      </ol>","frequence":1},{"id":"188-10","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d’une exacerbation d’asthme chez l’enfant et l’adulte","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Asthme aigu grave (AAG)</span> — urgence vitale.</strong> Reconnaître ≥ 1 signe = <span class=\"kw-alerte\">transfert médicalisé en réanimation</span>.\n      </div>\n      <h4>Signes de gravité — adulte et enfant</h4>\n      <table>\n        <thead><tr><th>Axe</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><th>Parole / conscience</th><td><ul><li>Parle avec des <strong>mots</strong> (pas des phrases)</li><li><span class=\"kw-alerte\">Confusion</span>, agitation, somnolence</li><li>Épuisement respiratoire</li></ul></td></tr>\n          <tr><th>Respiratoire</th><td><ul><li>FR <span class=\"kw-chiffre\">&gt; 30/min</span> (adulte)</li><li>Mise en jeu des <strong>muscles respiratoires accessoires</strong></li><li>Tirage sus-sternal, sus-claviculaire, intercostal</li><li><span class=\"kw-alerte\">Silence auscultatoire</span> (bronchospasme sévère)</li><li><span class=\"kw-alerte\">Cyanose</span></li></ul></td></tr>\n          <tr><th>Hémodynamique</th><td><ul><li>FC <span class=\"kw-chiffre\">&gt; 120/min</span> (adulte)</li><li>Pouls paradoxal <span class=\"kw-chiffre\">&gt; 20 mmHg</span></li><li>Bradycardie = signe d'épuisement</li></ul></td></tr>\n          <tr><th>Paraclinique</th><td><ul><li><span class=\"kw-bio\">SpO₂</span> <span class=\"kw-chiffre\">&lt; 90 %</span> en air ambiant</li><li><span class=\"kw-def\">DEP</span> <span class=\"kw-chiffre\">≤ 50 %</span> de la théorique ou du meilleur personnel</li><li>Normo/hypercapnie sur GDS = <span class=\"kw-alerte\">épuisement</span></li></ul></td></tr>\n        </tbody>\n      </table>\n      <h4>Terrain à haut risque</h4>\n      <ul>\n        <li>ATCD d'AAG, séjour en réa/intubation ;</li>\n        <li>Corticothérapie orale récente ou en cours ;</li>\n        <li>Hospitalisation pour asthme dans l'année ;</li>\n        <li>Consommation excessive de <span class=\"kw-ttt\">BDCA</span> ;</li>\n        <li>Non-observance, sous-utilisation des <span class=\"kw-ttt\">CSI</span> ;</li>\n        <li>Précarité socio-économique.</li>\n      </ul>","frequence":2},{"id":"188-11","rang":"B","rubrique":"Contenu multimédia","titre":"Connaître la sémiologie RP d’une distension thoracique","contenu":"<p>Sur la <strong><span class=\"kw-imagerie\">radiographie thoracique</span></strong> en <strong>inspiration</strong>, la distension pulmonaire (piégeage aérique) se traduit par :</p>\n      <table>\n        <thead><tr><th>Signe RP</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-imagerie\">Horizontalisation des côtes</span></th><td>Les arcs costaux postérieurs deviennent horizontaux (au lieu de leur pente descendante habituelle)</td></tr>\n          <tr><th><span class=\"kw-imagerie\">Aplatissement des coupoles diaphragmatiques</span></th><td>Perte de la convexité normale — coupoles rectilignes voire concaves</td></tr>\n          <tr><th><span class=\"kw-imagerie\">Hyperclarté pulmonaire diffuse</span></th><td>Bilatérale et symétrique, par piégeage aérique</td></tr>\n          <tr><th><span class=\"kw-imagerie\">Élargissement des espaces intercostaux</span></th><td>Distension du gril costal</td></tr>\n          <tr><th>Champs pulmonaires étendus</th><td>Comptage de <span class=\"kw-chiffre\">≥ 7 arcs costaux antérieurs</span> visibles au-dessus de la coupole droite</td></tr>\n          <tr><th>Silhouette cardiaque</th><td><span class=\"kw-alerte\">Cœur allongé et vertical</span> (« cœur en goutte ») par abaissement du diaphragme</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Intérêt.</strong> La <span class=\"kw-imagerie\">RXT</span> reste <strong>systématique à la 1<sup>re</sup> consultation</strong> et lors d'une <strong>exacerbation grave</strong> — surtout pour <strong>éliminer un diagnostic différentiel</strong> (pneumothorax, foyer, corps étranger, tumeur). Elle est <strong>normale en période intercritique</strong> chez l'asthmatique.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une distension isolée n'est pas spécifique de l'asthme — on la retrouve dans la BPCO, l'emphysème, la bronchiolite. Elle s'interprète toujours <strong>avec la clinique</strong>.\n      </div>","frequence":0},{"id":"188-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les grandes caractéristiques du syndrome obstructif en explorations fonctionnelles respiratoires (EFR) et les modalités d’interprétation d’un débit expiratoire de pointe (DEP)","contenu":"<h4>Syndrome ventilatoire obstructif (SVO)</h4>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Adulte</th><th>Enfant</th></tr></thead>\n        <tbody>\n          <tr><th>Critère de TVO</th><td><span class=\"kw-chiffre\">VEMS/CVF &lt; 0,7</span> (mesuré, pas prédit)</td><td><span class=\"kw-chiffre\">VEMS/CVF &lt; 0,8</span> ou <span class=\"kw-chiffre\">VEMS &lt; 80 %</span></td></tr>\n          <tr><th>Réversibilité <strong>partielle</strong> post-BDCA</th><td>↑ VEMS <span class=\"kw-chiffre\">≥ 200 mL</span> <strong>ET</strong> <span class=\"kw-chiffre\">≥ 12 %</span></td><td>↑ VEMS <span class=\"kw-chiffre\">≥ 12 %</span> et <span class=\"kw-chiffre\">≥ 200 mL</span></td></tr>\n          <tr><th>Réversibilité <strong>complète</strong></th><td>VEMS/CVF post <span class=\"kw-chiffre\">&gt; 0,7</span> <strong>ET</strong> VEMS post <span class=\"kw-chiffre\">&gt; 80 %</span></td><td>—</td></tr>\n          <tr><th>Hyperréactivité à la méthacholine</th><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span></td><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span></td></tr>\n          <tr><th>Provocation à l'effort</th><td>↓ VEMS <span class=\"kw-chiffre\">≥ 20 %</span></td><td>↓ VEMS <span class=\"kw-chiffre\">≥ 12 %</span></td></tr>\n        </tbody>\n      </table>\n      <h4>EFR selon l'âge (enfant)</h4>\n      <table>\n        <thead><tr><th>Âge</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-chiffre\">&lt; 3 ans</span></th><td><span class=\"kw-ci\">EFR non réalisées en routine</span></td></tr>\n          <tr><th><span class=\"kw-chiffre\">3-6 ans</span></th><td>Manœuvres forcées difficiles → techniques en ventilation spontanée : pléthysmographie, interruption de débit, oscillations forcées</td></tr>\n          <tr><th><span class=\"kw-chiffre\">&gt; 6 ans</span></th><td>Manœuvres forcées possibles → <strong>courbe débit-volume</strong> classique</td></tr>\n        </tbody>\n      </table>\n      <h4>Débit expiratoire de pointe (DEP)</h4>\n      <table>\n        <thead><tr><th>Item</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><th>Principe</th><td>Débit maximal instantané mesuré lors d'une expiration forcée</td></tr>\n          <tr><th>Limites</th><td>Moins fiable que le VEMS ; ne remplace pas la courbe débit-volume</td></tr>\n          <tr><th>Utilités</th><td><ul><li>Suivre l'évolution sous traitement d'une <strong>exacerbation grave</strong> aux urgences</li><li>Vérifier l'efficacité du traitement de fond</li><li>Diagnostic d'<strong>asthme professionnel</strong> (variabilité sur/hors travail)</li><li>Auto-surveillance par le patient</li></ul></td></tr>\n          <tr><th>Interprétation</th><td>Comparer au meilleur personnel ou à la valeur prédite. Seuil AAG : <span class=\"kw-chiffre\">DEP ≤ 50 %</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Fréquence des EFR chez l'enfant</h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">3-6 mois</span> après mise en route ou modification du traitement de fond ;</li>\n        <li>Puis <span class=\"kw-chiffre\">≥ 1x/an</span> (plus si asthme persistant sévère).</li>\n      </ul>","frequence":8},{"id":"188-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des tests immuno allergiques","contenu":"<h4>Indications</h4>\n      <table>\n        <thead><tr><th>Population</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><th>Adulte asthmatique</th><td>Bilan allergologique systématique (interrogatoire + prick-tests)</td></tr>\n          <tr><th>Enfant <span class=\"kw-chiffre\">&gt; 3 ans</span></th><td>Tout asthmatique</td></tr>\n          <tr><th>Enfant <span class=\"kw-chiffre\">&lt; 3 ans</span></th><td>Si ≥ 1 des critères :<ul><li>Signes respiratoires persistants, récidivants ou sévères</li><li>Traitement continu nécessaire</li><li>Signes extra-respiratoires évoquant une allergie</li></ul></td></tr>\n        </tbody>\n      </table>\n      <h4>Modalités — hiérarchie</h4>\n      <ol>\n        <li><strong>Prick-tests cutanés</strong> orientés par l'anamnèse — <span class=\"kw-chiffre\">1<sup>re</sup> intention</span> ;</li>\n        <li>Dosage des <span class=\"kw-bio\">IgE spécifiques</span> d'un pneumallergène — uniquement si <strong>discordance</strong> clinique/prick-tests, ou si prick-tests impossibles ;</li>\n        <li>Tests multiallergéniques in vitro (Phadiatop) — si tests cutanés difficiles à réaliser.</li>\n      </ol>\n      <div class=\"callout callout-info\">\n        <strong>Objectif.</strong> Identifier une <strong>sensibilisation</strong> (donc un mécanisme allergique) qui pourra justifier des <span class=\"kw-ttt\">mesures d'éviction</span> et éventuellement une <span class=\"kw-ttt\">immunothérapie allergénique</span>.\n      </div>","frequence":0},{"id":"188-14","rang":"A","rubrique":"Etiologies","titre":"Connaître les grandes étiologies professionnelles","contenu":"<h4>Deux grandes catégories mécanistiques</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Agents typiques</th></tr></thead>\n        <tbody>\n          <tr><th><strong>Avec</strong> latence — mécanisme <span class=\"kw-etio\">immunologique IgE-dépendant</span></th><td>Agents de <strong>haut poids moléculaire</strong> : farines de céréales, enzymes (alpha-amylase, cellulase), latex, protéines animales, acariens de stockage</td></tr>\n          <tr><th><strong>Avec</strong> latence — mécanisme <span class=\"kw-etio\">IgE non démontré</span></th><td>Agents de <strong>bas poids moléculaire</strong> : isocyanates, aldéhydes (para-, glutaraldéhyde), persulfates, acrylates, amines aliphatiques, ammoniums quaternaires</td></tr>\n          <tr><th><strong>Sans</strong> latence — Syndrome de <span class=\"kw-def\">Brooks</span></th><td>Exposition accidentelle unique ou faibles doses répétées d'irritants respiratoires (vapeur, gaz, fumée : chlore, ammoniac, oxydes d'azote)</td></tr>\n        </tbody>\n      </table>\n      <h4>Familles d'agents à retenir</h4>\n      <ul>\n        <li><strong>Farines et enzymes</strong> — boulangers, meuniers ;</li>\n        <li><strong>Latex</strong> — santé, industrie caoutchouc ;</li>\n        <li><strong>Isocyanates</strong> — peinture polyuréthane, mousses, colles ;</li>\n        <li><strong>Aldéhydes et ammoniums quaternaires</strong> — désinfection, nettoyage ;</li>\n        <li><strong>Persulfates</strong> — coiffure ;</li>\n        <li><strong>Bois et colles</strong> — menuiserie, ébénisterie ;</li>\n        <li><strong>Protéines animales</strong> — vétérinaires, éleveurs, laboratoires.</li>\n      </ul>","frequence":0},{"id":"188-15","rang":"B","rubrique":"Etiologies","titre":"Connaître les principaux facteurs de non contrôle de l’asthme et savoir rechercher les facteurs précipitants d’un asthme aigu grave","contenu":"<h4>Facteurs de non-contrôle — à rechercher systématiquement</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><th>Observance / technique</th><td><ul><li>Non-observance du <span class=\"kw-ttt\">traitement de fond</span> (<span class=\"kw-chiffre\">50 %</span> chez l'enfant)</li><li>Mauvaise technique d'inhalation</li><li>Posologie de <span class=\"kw-ttt\">CSI</span> inadaptée</li></ul></td></tr>\n          <tr><th>Expositions persistantes</th><td><ul><li>Allergène en cas de sensibilisation (acariens, animaux, moisissures)</li><li><span class=\"kw-etio\">Tabagisme</span> actif ou passif</li><li>Pollution atmosphérique</li><li>Exposition professionnelle non éliminée</li></ul></td></tr>\n          <tr><th>Comorbidités allergiques</th><td>Rhinoconjonctivite, allergie alimentaire IgE-médiée, dermatite atopique</td></tr>\n          <tr><th>Comorbidités non allergiques</th><td><ul><li>Obésité</li><li>Rhinosinusite chronique, polypose</li><li><span class=\"kw-def\">RGO</span></li><li>Syndrome d'hyperventilation</li><li>Dyskinésie des cordes vocales</li><li><span class=\"kw-def\">SAHOS</span></li></ul></td></tr>\n          <tr><th>Iatrogène</th><td><ul><li><span class=\"kw-ci\">β-bloquants</span> (même en collyre)</li><li><span class=\"kw-ci\">AINS et aspirine</span> chez les sujets sensibles</li></ul></td></tr>\n          <tr><th>Autres</th><td>Problèmes psychologiques/socio-économiques ; éosinophilie ; grossesse mal suivie</td></tr>\n        </tbody>\n      </table>\n      <h4>Facteurs précipitants d'un <span class=\"kw-alerte\">AAG</span></h4>\n      <ul>\n        <li><span class=\"kw-etio\">Infection virale</span> respiratoire ;</li>\n        <li>Exposition massive à un allergène ;</li>\n        <li>Prise d'<span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">β-bloquants</span> ;</li>\n        <li>Arrêt brutal du <span class=\"kw-ttt\">traitement de fond</span> ;</li>\n        <li>Sous-traitement chronique ;</li>\n        <li>Stress, effort intense en air froid ;</li>\n        <li>Non-reconnaissance des signes de gravité par le patient (absence de plan d'action).</li>\n      </ul>","frequence":1},{"id":"188-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques de la rhinite allergique","contenu":"<h4>Traitement médicamenteux</h4>\n      <p>Soit en <strong>traitement de fond</strong>, soit <strong>ponctuel</strong> (pas de préférence en 1<sup>re</sup> intention, peuvent être associés) :</p>\n      <table>\n        <thead><tr><th>Classe</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-ttt\">Anti-histaminiques H1</span> de 2<sup>e</sup> génération (PO ± local)</th><td><span class=\"kw-chiffre\">1<sup>re</sup> intention</span> — plutôt symptômes <strong>intermittents</strong></td></tr>\n          <tr><th><span class=\"kw-ttt\">Corticoïdes nasaux</span></th><td>Symptômes <strong>persistants</strong> ou <strong>obstruction nasale</strong> prédominante</td></tr>\n        </tbody>\n      </table>\n      <h4>Traitement non médicamenteux</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Lavages nasaux</span> au sérum physiologique ;</li>\n        <li>Sevrage <span class=\"kw-etio\">tabagique</span> ;</li>\n        <li>Prise en charge du stress et de l'anxiété (retentissement fréquent sur le sommeil).</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Vasoconstricteurs nasaux déconseillés au long cours</span></strong> :\n        <ul>\n          <li>Risque de <span class=\"kw-alerte\">rhinite iatrogène</span> (rebond) ;</li>\n          <li>Risque de <span class=\"kw-alerte\">coronarospasme</span> chez le coronarien.</li>\n        </ul>\n      </div>\n      <h4>Prise en charge du facteur allergique</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Mesures d'éviction</span> (souvent difficiles) ;</li>\n        <li><span class=\"kw-ttt\">Immunothérapie allergénique</span> — indication de choix : RCA <strong>saisonnière</strong> (graminées, bouleau). Elle améliore les scores symptomatiques, à court et long terme, et <strong>réduit le risque d'apparition d'un asthme chez l'enfant avec RCA</strong>. Moins efficace en cas de RCA peranuelle ou de polyallergies.</li>\n      </ul>","frequence":3},{"id":"188-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes thérapeutiques de fond de la maladie asthmatique avec les principales classes thérapeutiques utilisables","contenu":"<div class=\"callout callout-info\">\n        <strong>Principe fondamental.</strong> Le traitement de fond est <strong>initié dès que le diagnostic est évoqué</strong> (symptômes <span class=\"kw-chiffre\">&gt; 2x/mois</span>), pris <strong>tous les jours</strong>, et repose sur une <span class=\"kw-ttt\">corticothérapie inhalée</span>. <span class=\"kw-ci\">L'asthme ne se traite jamais par bronchodilatateur seul</span>.\n      </div>\n      <h4>Paliers thérapeutiques GINA (adulte / adolescent ≥ 12 ans)</h4>\n      <table>\n        <thead><tr><th>Palier</th><th>Traitement de fond</th><th>Options</th><th>Secours</th></tr></thead>\n        <tbody>\n          <tr><th>1</th><td>Pas de tt de fond</td><td>Envisager <span class=\"kw-ttt\">CSI</span> faible dose</td><td><span class=\"kw-ttt\">BDCA</span> à la demande ou <span class=\"kw-ttt\">CSI + formotérol</span></td></tr>\n          <tr><th>2</th><td><span class=\"kw-ttt\">CSI</span> faible dose</td><td><span class=\"kw-ttt\">Anti-leucotriènes</span> (ALT)</td><td>id.</td></tr>\n          <tr><th>3</th><td><span class=\"kw-ttt\">CSI</span> faible dose + <span class=\"kw-ttt\">BDLA</span></td><td><span class=\"kw-ttt\">CSI</span> dose modérée ou <span class=\"kw-ttt\">CSI</span> faible + ALT</td><td>id.</td></tr>\n          <tr><th>4</th><td><span class=\"kw-ttt\">CSI</span> dose modérée + <span class=\"kw-ttt\">BDLA</span></td><td><span class=\"kw-ttt\">CSI</span> dose forte + ALT ou <span class=\"kw-ttt\">tiotropium</span></td><td>id.</td></tr>\n          <tr><th>5</th><td><span class=\"kw-ttt\">CSI</span> dose forte + <span class=\"kw-ttt\">BDLA</span> + adresser au centre d'asthme sévère<br>+ <span class=\"kw-ttt\">tiotropium</span>, anti-IgE, anti-IL5, autres biothérapies</td><td><span class=\"kw-ttt\">CSO</span> faible dose (dernier recours)</td><td>id.</td></tr>\n        </tbody>\n      </table>\n      <h4>Traitement de secours (crise / symptômes)</h4>\n      <ul>\n        <li><strong>Adolescent ≥ 12 ans, adulte</strong> : association <span class=\"kw-ttt\">CSI + formotérol</span> (BDLA d'action rapide) dans le même dispositif. Le <span class=\"kw-ttt\">BDCA seul</span> n'est plus recommandé (surrisque d'exacerbation sévère et de décès) ;</li>\n        <li><strong>Enfant &lt; 12 ans</strong> : <span class=\"kw-ttt\">β2-mimétiques courte durée d'action</span> (BDCA) ± adjonction transitoire d'un <span class=\"kw-ttt\">CSI</span>.</li>\n      </ul>\n      <h4>Classes thérapeutiques principales</h4>\n      <table>\n        <thead><tr><th>Classe</th><th>Molécules</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-ttt\">CSI</span></th><td>Béclométasone, budésonide, fluticasone…</td><td>Anti-inflammatoire de base — pierre angulaire</td></tr>\n          <tr><th><span class=\"kw-ttt\">BDCA</span></th><td>Salbutamol, terbutaline</td><td>Traitement de secours — bronchodilatation rapide</td></tr>\n          <tr><th><span class=\"kw-ttt\">BDLA</span></th><td>Salmétérol, formotérol</td><td>Toujours en <strong>association avec CSI</strong>, à partir du palier 3 (adulte) ou <span class=\"kw-chiffre\">≥ 4 ans</span> (enfant)</td></tr>\n          <tr><th>Anti-leucotriènes (ALT)</th><td>Montélukast</td><td>Alternative aux CSI ou en association ; EI neuropsychiatriques (cauchemars, dépression) → arrêt</td></tr>\n          <tr><th>Anti-cholinergique longue durée</th><td>Tiotropium</td><td>Paliers 4-5 en add-on</td></tr>\n          <tr><th>Biothérapies</th><td>Omalizumab (anti-IgE), mépolizumab/reslizumab (anti-IL5), dupilumab (anti-IL4R)…</td><td>Asthme sévère palier 5, ≥ 6 ans</td></tr>\n          <tr><th><span class=\"kw-ttt\">CSO</span></th><td>Prednisone, prednisolone</td><td>Cure courte pour exacerbation ; <span class=\"kw-ci\">jamais en fond chez l'enfant sauf exception</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Mesures associées systématiques</h4>\n      <ul>\n        <li>Sevrage <span class=\"kw-etio\">tabagique</span> (encouragement fort et répété) ;</li>\n        <li>Activité physique régulière ;</li>\n        <li>Éviction des irritants domestiques et professionnels ;</li>\n        <li><span class=\"kw-ci\">β-bloquants</span> déconseillés (avis pneumo indispensable) ;</li>\n        <li><span class=\"kw-ci\">Aspirine / AINS</span> CI si ATCD d'hypersensibilité ;</li>\n        <li><span class=\"kw-ttt\">Vaccinations</span> : grippe annuelle, pneumocoque, COVID-19.</li>\n      </ul>","frequence":4},{"id":"188-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités d’utilisation des beta-2 mimétiques (inhalation, aérosol) et des corticoïdes inhalés dans la maladie asthmatique","contenu":"<h4>Corticoïdes inhalés (<span class=\"kw-ttt\">CSI</span>)</h4>\n      <table>\n        <thead><tr><th>Item</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th>Indication de fond</th><td>Dès le palier 2 (adulte) ; enfant préscolaire avec critères de non-contrôle ou <span class=\"kw-chiffre\">≥ 3</span> exacerbations l'année précédente</td></tr>\n          <tr><th>Prise</th><td>Quotidienne, aux mêmes horaires ; <strong>rinçage de la bouche</strong> après chaque prise</td></tr>\n          <tr><th>Dose</th><td>Dose minimale efficace ; palier de traitement défini selon l'âge et la molécule</td></tr>\n          <tr><th>Effets secondaires locaux</th><td>Candidose oropharyngée, dysphonie, dermite péri-orale — prévenus par la <strong>chambre d'inhalation</strong> + rinçage buccal</td></tr>\n          <tr><th>Effets secondaires systémiques</th><td>Rares aux doses usuelles ; ralentissement transitoire de la vitesse de croissance en début de tt chez l'enfant (perte de taille finale possible <span class=\"kw-chiffre\">&lt; 1 cm</span>) → dose minimale efficace + surveillance staturale</td></tr>\n        </tbody>\n      </table>\n      <h4>β2-mimétiques</h4>\n      <table>\n        <thead><tr><th>Classe</th><th>Molécules</th><th>Utilisation</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-ttt\">BDCA</span> — courte durée</th><td>Salbutamol, terbutaline</td><td>Traitement de secours (bouffées à la demande) ; en <strong>nébulisation</strong> aux urgences pour exacerbation grave : <span class=\"kw-chiffre\">5 mg</span>/20 min × 3 puis en continu</td></tr>\n          <tr><th><span class=\"kw-ttt\">BDLA</span> — longue durée</th><td>Salmétérol, formotérol</td><td>Toujours <strong>en association fixe avec un CSI</strong> ; à partir de <span class=\"kw-chiffre\">≥ 4 ans</span> chez l'enfant ; le formotérol est le seul BDLA d'action rapide utilisable comme secours dans les stratégies MART/AIR (CSI + formotérol)</td></tr>\n        </tbody>\n      </table>\n      <h4>Effets secondaires des β2-mimétiques</h4>\n      <ul>\n        <li>BDCA : tachycardie, tremblements, céphalées, crampes, <span class=\"kw-bio\">hypokaliémie</span> ;</li>\n        <li>BDLA : tachycardie, céphalées, crampes.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">BDLA en monothérapie interdit</span></strong> — surrisque d'exacerbation grave et de décès. Toujours associé à un <span class=\"kw-ttt\">CSI</span>.\n      </div>\n      <h4>Choix du dispositif d'inhalation selon l'âge</h4>\n      <table>\n        <thead><tr><th>Âge</th><th>Dispositif</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-chiffre\">≤ 3-4 ans</span></th><td>Aérosol-doseur + chambre d'inhalation + <strong>masque facial</strong>. Nébulisations pneumatiques si forme sévère</td></tr>\n          <tr><th><span class=\"kw-chiffre\">3/4 → 6/7 ans</span></th><td>Aérosol-doseur + chambre d'inhalation avec <strong>embout buccal</strong></td></tr>\n          <tr><th><span class=\"kw-chiffre\">6/7 → 9/10 ans</span></th><td>Aérosols-doseurs auto-déclenchés ; inhalateurs de poudre sèche (débit inspiratoire <span class=\"kw-chiffre\">≥ 30 L/min</span>) après vérification technique</td></tr>\n          <tr><th>Après <span class=\"kw-chiffre\">9-10 ans</span></th><td>Aérosol-doseur classique — coordination main-poumon acquise</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"188-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l’asthme en première intention","contenu":"<h4>Objectifs du traitement de fond</h4>\n      <ul>\n        <li>Contrôler les symptômes et permettre une activité normale ;</li>\n        <li>Réduire le risque d'<span class=\"kw-def\">exacerbation</span> ;</li>\n        <li>Prévenir l'altération de la fonction respiratoire ;</li>\n        <li>Minimiser les effets secondaires du traitement ;</li>\n        <li>Rechercher la <strong>dose minimale efficace</strong>.</li>\n      </ul>\n      <h4>Rythme de surveillance</h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><th>Après initiation ou modification du tt de fond</th><td>Consultation à <span class=\"kw-chiffre\">1-3 mois</span> (adulte) ou <span class=\"kw-chiffre\">3-6 mois</span> (enfant)</td></tr>\n          <tr><th>Suivi périodique</th><td>Adapté à la sévérité, minimum <span class=\"kw-chiffre\">≥ 1x/an</span></td></tr>\n          <tr><th>Femme enceinte</th><td>Suivi <strong>mensuel</strong></td></tr>\n          <tr><th>EFR (enfant en âge)</th><td><span class=\"kw-chiffre\">≥ 1x/an</span> — plus si asthme persistant sévère</td></tr>\n        </tbody>\n      </table>\n      <h4>Contenu de la consultation de suivi</h4>\n      <ol>\n        <li>Contrôle des symptômes sur 4 semaines (<span class=\"kw-def\">ACT</span>) ;</li>\n        <li>Vérification de l'<strong>observance</strong> ;</li>\n        <li>Vérification de la <strong>technique d'inhalation</strong> ;</li>\n        <li>Recherche de <span class=\"kw-etio\">facteurs favorisants</span> persistants (tabac, allergène, RGO, obésité) ;</li>\n        <li>Effets secondaires du traitement ;</li>\n        <li>Compréhension du <span class=\"kw-def\">plan d'action</span> écrit ;</li>\n        <li>Retentissement scolaire, social, familial ;</li>\n        <li>Fonction respiratoire (VEMS, DEP).</li>\n      </ol>\n      <h4>Adaptation du traitement</h4>\n      <ul>\n        <li><strong>Asthme contrôlé</strong> → <span class=\"kw-alerte\">step-down</span> à la dose minimale efficace, jamais en dessous d'un CSI faible dose (adulte/ado) ;</li>\n        <li><strong>Asthme non contrôlé</strong> → vérifier les 3 points ci-dessus puis <span class=\"kw-alerte\">step-up</span> au palier supérieur.</li>\n      </ul>\n      <h4>Quand adresser au pneumologue ?</h4>\n      <ul>\n        <li>Doute sur un diagnostic différentiel ou associé ;</li>\n        <li>EFR non disponibles ou VEMS <span class=\"kw-chiffre\">&lt; 80 %</span> ;</li>\n        <li>≥ 2 exacerbations/an malgré un bon suivi ;</li>\n        <li>Recours à un <span class=\"kw-ttt\">CSI</span> dose moyenne/forte ;</li>\n        <li>Contrôle non obtenu malgré une PEC adaptée ;</li>\n        <li>Asthme sévère (palier 4 ou 5).</li>\n      </ul>","frequence":1},{"id":"188-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’initiation du traitement d’urgence d’une crise d’asthme chez l’enfant et l’adulte","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">AAG</span> — transfert médicalisé immédiat en réanimation.</strong> À domicile en attendant : <span class=\"kw-ttt\">β2-mimétiques fortes doses</span> par chambre d'inhalation.\n      </div>\n      <h4>Exacerbation sévère / AAG — hôpital</h4>\n      <ol>\n        <li><span class=\"kw-ttt\">Oxygénothérapie</span> — objectif <span class=\"kw-bio\">SpO₂</span> <span class=\"kw-chiffre\">93-95 %</span> (adulte) ou <span class=\"kw-chiffre\">94-98 %</span> ;</li>\n        <li><span class=\"kw-ttt\">β2-mimétiques nébulisés</span> — salbutamol <span class=\"kw-chiffre\">5 mg</span> toutes les <span class=\"kw-chiffre\">20 min</span> pendant 1 h (≥ 3 nébulisations) puis en continu ;</li>\n        <li><span class=\"kw-ttt\">± Ipratropium</span> <span class=\"kw-chiffre\">0,5 mg</span> toutes les <span class=\"kw-chiffre\">8 h</span> si réponse insuffisante ;</li>\n        <li><span class=\"kw-ttt\">Corticothérapie systémique</span> en <span class=\"kw-chiffre\">&lt; 1 h</span> — prednisone/prednisolone <span class=\"kw-chiffre\">0,5-1 mg/kg/j</span> (max <span class=\"kw-chiffre\">60-80 mg</span>) pendant <span class=\"kw-chiffre\">5-7 j</span>, sans décroissance ;</li>\n        <li>Échec des BDCA nébulisés → <span class=\"kw-ttt\">salbutamol IV</span> (seringue électrique, scope, surveillance <span class=\"kw-bio\">hypokaliémie</span>) ;</li>\n        <li>Gravité extrême → <span class=\"kw-ttt\">ventilation mécanique</span> (VNI puis intubation).</li>\n      </ol>\n      <h4>Exacerbation modérée — ambulatoire ou courte hospit.</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">β2-mimétiques fortes doses</span> par chambre d'inhalation (≥ 3 administrations en 1 h) ;</li>\n        <li><span class=\"kw-ttt\">Corticothérapie orale</span> <span class=\"kw-chiffre\">0,5-1 mg/kg/j</span> pendant <span class=\"kw-chiffre\">5-7 j</span> ;</li>\n        <li><span class=\"kw-ttt\">O₂</span> si hypoxémie ;</li>\n        <li>Réévaluation à H1 : dyspnée, FR, auscultation, PA, SpO₂, DEP répété. Absence d'amélioration → transfert en soins intensifs.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>À ne <span class=\"kw-ci\">jamais</span> utiliser dans l'AAG.</strong>\n        <ul>\n          <li><span class=\"kw-ci\">BDLA</span>, <span class=\"kw-ci\">théophylline</span> ;</li>\n          <li><span class=\"kw-ci\">Sédatifs</span> ;</li>\n          <li><span class=\"kw-ci\">Mucolytiques</span>, <span class=\"kw-ci\">antitussifs</span> ;</li>\n          <li><span class=\"kw-ci\">Réhydratation agressive</span>.</li>\n        </ul>\n      </div>\n      <h4>Après amélioration — sortie</h4>\n      <ul>\n        <li>Normalisation du <span class=\"kw-def\">DEP</span> et disparition des symptômes à H1 → retour à domicile ;</li>\n        <li>Initier ou majorer le <span class=\"kw-ttt\">traitement de fond</span> ;</li>\n        <li>Poursuivre la <span class=\"kw-ttt\">CTC orale</span> <span class=\"kw-chiffre\">5-7 j</span> ;</li>\n        <li>Remettre / expliquer le <span class=\"kw-def\">plan d'action écrit</span> ;</li>\n        <li>Consultation de suivi à <span class=\"kw-chiffre\">1-4 semaines</span>.</li>\n      </ul>","frequence":4},{"id":"188-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de l’éducation thérapeutique de l’asthme et les plans d’action pour améliorer l’observance dans l’asthme","contenu":"<h4>Objectifs de l'éducation thérapeutique</h4>\n      <ul>\n        <li>Comprendre les mécanismes de la maladie ;</li>\n        <li>Identifier les facteurs déclencheurs et savoir les prévenir ;</li>\n        <li>Maîtriser la <strong>technique d'inhalation</strong> ;</li>\n        <li>Mesurer et interpréter son <span class=\"kw-def\">DEP</span> ;</li>\n        <li>Reconnaître les signes de perte de contrôle et d'exacerbation ;</li>\n        <li>Reconnaître les <span class=\"kw-alerte\">signes de gravité</span> nécessitant un recours médical urgent ;</li>\n        <li>Autogérer une crise débutante (plan d'action) ;</li>\n        <li>Connaître et observer le traitement de fond.</li>\n      </ul>\n      <h4>Plan d'action écrit — contenu obligatoire</h4>\n      <ol>\n        <li><strong>Signes cliniques</strong> à identifier, dont ceux imposant d'appeler les secours ;</li>\n        <li><strong>Médicaments de secours</strong> à utiliser (BDCA ± CSI), doses, fréquence ;</li>\n        <li>Recours à la <span class=\"kw-ttt\">corticothérapie orale</span> (indications, doses) ;</li>\n        <li>Éventuelle <strong>augmentation du traitement de fond</strong> pendant <span class=\"kw-chiffre\">1-2 semaines</span> ;</li>\n        <li>Indications de <strong>consultation médicale urgente</strong> / appel du 15.</li>\n      </ol>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <strong>Tous</strong> les enfants et adolescents doivent avoir un plan d'action écrit, individualisé, tenant compte du niveau de contrôle. Chez l'adulte, il est <strong>fortement recommandé</strong>.\n      </div>\n      <h4>Mesures sociales</h4>\n      <ul>\n        <li><strong>PAI</strong> (Projet d'Accueil Individualisé) — gestion de la crise à l'école, à la crèche, en collectivité ;</li>\n        <li>Prise en charge <strong>ALD à 100 %</strong> pour les asthmes les plus sévères.</li>\n      </ul>","frequence":0},{"id":"188-22","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","contenu":"<h4>Éviction — allergènes domestiques</h4>\n      <table>\n        <thead><tr><th>Allergène</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Acariens</span></th><td><ul><li>Housses anti-acariens (matelas, oreillers, couette)</li><li>Aération quotidienne, température <span class=\"kw-chiffre\">&lt; 20 °C</span></li><li>Diminuer l'humidité (<span class=\"kw-chiffre\">&lt; 50 %</span>)</li><li>Lavage draps à <span class=\"kw-chiffre\">≥ 60 °C</span></li><li>Éviter moquettes, tentures, peluches</li><li>Aspirateur avec filtre HEPA</li></ul></td></tr>\n          <tr><th><span class=\"kw-etio\">Animaux domestiques</span> (chat, chien, cheval, NAC)</th><td><ul><li>Idéal : <strong>éviction complète</strong></li><li>Sinon : animal exclu de la chambre</li><li>Pas d'acquisition d'un nouvel animal</li></ul></td></tr>\n          <tr><th><span class=\"kw-etio\">Moisissures</span></th><td>Réparer les fuites, aérer, ventilation efficace, nettoyage à l'eau de Javel des zones contaminées</td></tr>\n          <tr><th><span class=\"kw-etio\">Blattes</span></th><td>Hygiène rigoureuse, désinsectisation, obturation des accès</td></tr>\n        </tbody>\n      </table>\n      <h4>Éviction — allergènes extérieurs</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Pollens</span> : fermer les fenêtres pendant les pics, lunettes de soleil, douche/lavage de cheveux le soir, consulter les bulletins polliniques (RNSA), pas d'activité extérieure prolongée en période de pic ;</li>\n        <li>Éviter les <span class=\"kw-etio\">irritants</span> : tabac (actif et passif), pollution atmosphérique aux pics.</li>\n      </ul>\n      <h4>Mesures d'éviction professionnelle</h4>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th>1. Éviction de l'agent</th><td>Substitution du produit, encapsulage, aspiration à la source, EPI (masques adaptés)</td></tr>\n          <tr><th>2. Aménagement de poste</th><td>Via le médecin du travail — reclassement si nécessaire</td></tr>\n          <tr><th>3. Déclaration</th><td>Déclaration en <strong>maladie professionnelle</strong> (tableaux 66, 66 bis, 62, 47…) — <strong>délai de PEC <span class=\"kw-chiffre\">7 j</span></strong></td></tr>\n          <tr><th>4. Suivi</th><td>Surveillance médicale renforcée, EFR régulières</td></tr>\n        </tbody>\n      </table>\n      <h4>Immunothérapie allergénique (ITA / désensibilisation)</h4>\n      <ul>\n        <li>Indication de choix : rhinite allergique <strong>saisonnière</strong> monosensibilisée (graminées, bouleau) ;</li>\n        <li>Asthme allergique aux acariens bien contrôlé (voie sublinguale) ;</li>\n        <li>Réduit le risque d'apparition d'un asthme chez l'enfant avec RCA ;</li>\n        <li>Moins efficace en cas de polyallergie.</li>\n      </ul>","frequence":4},{"id":"188-23","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications de l’asthme","contenu":"<h4>Complications aiguës</h4>\n      <table>\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-alerte\">Asthme aigu grave (AAG)</span></th><td>Urgence vitale — <span class=\"kw-chiffre\">~1000 décès/an</span> en France (adulte)</td></tr>\n          <tr><th><span class=\"kw-alerte\">Pneumothorax / pneumomédiastin</span></th><td>Par barotraumatisme — rare mais grave</td></tr>\n          <tr><th>Surinfection bronchique</th><td>Volontiers virale ; suspecter atypique/pyogène si expectoration purulente prolongée</td></tr>\n          <tr><th>Atélectasies</th><td>Par bouchon muqueux — surtout enfant</td></tr>\n        </tbody>\n      </table>\n      <h4>Complications chroniques</h4>\n      <ul>\n        <li><strong>Remodelage bronchique</strong> irréversible → <span class=\"kw-def\">TVO fixé</span> non réversible ;</li>\n        <li><strong>Insuffisance respiratoire chronique obstructive</strong> à long terme ;</li>\n        <li><strong>Aspergillose bronchopulmonaire allergique (ABPA)</strong> — à évoquer devant asthme mal contrôlé + éosinophilie + IgE totales élevées + IgE spécifiques anti-Aspergillus + bronchectasies proximales ;</li>\n        <li><strong>Granulomatose éosinophilique avec polyangéite (Churg-Strauss)</strong> — asthme sévère + éosinophilie + atteinte multi-organe ;</li>\n        <li><strong>Retentissement scolaire/professionnel</strong>, absentéisme.</li>\n      </ul>\n      <h4>Complications iatrogènes</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">CSI</span> forte dose au long cours : candidose oropharyngée, dysphonie, ecchymoses, ostéoporose, retard de croissance transitoire chez l'enfant ;</li>\n        <li><span class=\"kw-ttt\">CSO</span> au long cours (asthme sévère palier 5) : diabète cortico-induit, HTA, ostéoporose, cataracte, myopathie ;</li>\n        <li><span class=\"kw-ttt\">β2-mimétiques</span> forte dose : tachycardie, tremblements, hypokaliémie.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Signes évocateurs d'ABPA — à connaître.</strong>\n        <ol>\n          <li>Asthme corticorésistant ou aggravation inexpliquée ;</li>\n          <li>Éosinophilie sanguine <span class=\"kw-chiffre\">&gt; 500/mm³</span> ;</li>\n          <li>IgE totales <span class=\"kw-chiffre\">&gt; 1000 UI/mL</span> ;</li>\n          <li>IgE et précipitines spécifiques anti-<em>Aspergillus fumigatus</em> ;</li>\n          <li>Bronchectasies proximales sacciformes en TDM.</li>\n        </ol>\n      </div>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/asthme","label":"pedia-univ.fr"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_188_ASTHME_RHINITE_2023.pdf","label":"cep-1f48c.kxcdn.com"},{"href":"https://www.uphoc.com/files/uploads/2017/10/BUM_asthme_test_ACT.pdf","label":"uphoc.com"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/23.%20Exacerbation%20s%C3%A9v%C3%A8re%20d%27asthme.pdf","label":"ce-mir.fr"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Exacerbation d'asthme aiguë — Évaluer : examen clinique + DEP + SpO2","detail":"<h4>CAT — Exacerbation d'asthme aiguë — Stratification de la gravité → orientation (collège de pneumologie)</h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité présents ? — Parle avec des mots, FR > 30, FC > 120, <span class=\"kw-bio\">SpO2</span> < 90%, DEP ≤ 50%, muscles accessoires","branches":[{"to":"t-severe","label":"Signes de gravité présents","color":"red"},{"to":"q-duree","label":"Pas de signe de gravité","color":"green"}]},{"id":"t-severe","kind":"terminal","label":"Exacerbation sévère (AAG) — hospitalisation immédiate","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Transport médicalisé + transfert en USI d'emblée</span> ; à domicile en attendant : <span class=\"kw-ttt\">β2-mimétiques fortes doses</span></li><li>Hôpital : <span class=\"kw-ttt\">oxygénothérapie</span> (objectif <span class=\"kw-bio\">SpO2</span> <span class=\"kw-chiffre\">93-95%</span>) + <span class=\"kw-ttt\">β2 nébulisés</span><span class=\"kw-chiffre\"> 5 mg</span> toutes les <span class=\"kw-chiffre\">20 min</span> (≥ 3 administrations) ou en continu</li><li><span class=\"kw-ttt\">± ipratropium</span><span class=\"kw-chiffre\"> 0,5 mg</span> toutes les <span class=\"kw-chiffre\">8h</span> si réponse insuffisante</li><li><span class=\"kw-ttt\">Corticothérapie systémique</span> en <span class=\"kw-chiffre\">&lt; 1h</span> (<span class=\"kw-ttt\">prednisolone</span>/<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">0,5-1 mg/kg/j</span>, max <span class=\"kw-chiffre\">80 mg</span>, 5-7 j)</li><li>Échec des BDCA → <span class=\"kw-ttt\">salbutamol IV</span> (seringue électrique, scope : <span class=\"kw-bio\">hypokaliémie</span>) ; <span class=\"kw-ttt\">ventilation mécanique</span> si gravité extrême</li></ul><h4>À ne pas utiliser</h4><ul><li><span class=\"kw-ci\">BDLA, théophylline, sédatif, mucolytiques, antitussifs, réhydratation agressive</span></li></ul>"},{"id":"q-duree","kind":"decision","label":"Exacerbation installée depuis ≥ 2 jours ? — ≥ 2 jours = exacerbation ; sinon perte de contrôle récente","branches":[{"to":"t-moderee","label":"Exacerbation ≥ 2 jours","color":"amber"},{"to":"q-h1","label":"Perte de contrôle récente","color":"green"}]},{"id":"t-moderee","kind":"terminal","label":"Exacerbation modérée — traitement ambulatoire","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">β2-mimétiques fortes doses</span> (≥ 3 administrations en <span class=\"kw-chiffre\">1h</span>, chambre d'inhalation)</li><li><span class=\"kw-ttt\">Corticothérapie orale</span> <span class=\"kw-chiffre\">5-7 jours</span> (<span class=\"kw-ttt\">prednisolone</span>/<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">0,5-1 mg/kg/j</span>, max <span class=\"kw-chiffre\">60 mg</span>, sans décroissance)</li><li><span class=\"kw-ttt\">O2</span> si hypoxémie, objectif <span class=\"kw-chiffre\">SpO2 94-98%</span></li></ul><h4>Surveillance</h4><ul><li>Réévaluation : dyspnée, FR, auscultation, pouls, PA, <span class=\"kw-bio\">SpO2</span> + mesure répétée du <span class=\"kw-def\">DEP</span></li><li>Pas d'amélioration après <span class=\"kw-chiffre\">1h</span> → transfert en soins intensifs (traitement de l'exacerbation sévère)</li></ul>"},{"id":"q-h1","kind":"decision","label":"Réévaluation à H1 ? — Après β2 inhalé 2-8 bouffées (chambre d'inhalation)","branches":[{"to":"t-domicile","label":"DEP normalisé + symptômes résolus","color":"green"},{"to":"t-hospit","label":"Persistance des symptômes","color":"amber"}]},{"id":"t-domicile","kind":"terminal","label":"Retour à domicile","color":"green","detail":"<h4>Conduite</h4><ul><li>Normalisation du <span class=\"kw-def\">DEP</span> et disparition des symptômes à H1</li><li>Initier ou majorer le <span class=\"kw-ttt\">traitement de fond</span> à l'occasion de l'exacerbation</li><li>Remettre/expliquer le <span class=\"kw-def\">plan d'action écrit</span></li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Persistance à H1 — discuter une hospitalisation","color":"amber","detail":"<h4>Conduite</h4><ul><li>Persistance des symptômes malgré les <span class=\"kw-ttt\">β2 inhalés</span> → discussion d'une hospitalisation</li><li>Poursuite des <span class=\"kw-ttt\">β2 fortes doses</span> ± <span class=\"kw-ttt\">corticothérapie orale</span></li><li>Surveillance clinique + <span class=\"kw-def\">DEP</span> répétés</li></ul>"}]},"cards":[{"i":"08d9b1e17b0f","n":188,"o":"188-1","u":"Définition","t":"Connaître la définition de l’asthme et de la rhinite allergique (chez l’adulte et l’enfant, selon l’âge chez l’enfant)","q":"Quelle est la définition de la rhinite allergique chez l'adulte et l'enfant ?","a":"<p>La rhinite allergique est une <strong>inflammation chronique de la muqueuse nasale</strong>, induite par une <strong>réaction d'hypersensibilité de type 1</strong> médiée par les IgE, en réponse à des allergènes spécifiques, et caractérisée par une <strong>rhinorrhée</strong>, des <strong>éternuements</strong>, un <strong>prurit nasal</strong> et une <strong>obstruction nasale</strong>.</p>"},{"i":"aefb07301090","n":188,"o":"188-1","u":"Définition","t":"Connaître la définition de l’asthme et de la rhinite allergique (chez l’adulte et l’enfant, selon l’âge chez l’enfant)","q":"Quelle est la définition de l'asthme chez l'adulte et l'enfant ?","a":"<p>L'asthme est une <strong>maladie inflammatoire chronique des voies aériennes</strong>, caractérisée par une <strong>hyperréactivité bronchique</strong> entraînant une <strong>obstruction bronchique réversible</strong>, spontanément ou sous l'effet d'un traitement bronchodilatateur.</p>"},{"i":"28f9b9497c63","n":188,"o":"188-10","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les signes cliniques de gravité d'une exacerbation d'asthme chez l'enfant ?","a":"<p>Chez l'enfant, les signes de gravité d'une exacerbation d'asthme incluent :</p><ul><li>Des <strong>troubles de la conscience</strong> (agitation, léthargie).</li><li>Une <strong>cyanose</strong>.</li><li>Un <strong>tirage respiratoire intense</strong> (sus-sternal, intercostal, sous-costal).</li><li>Une <strong>respiration paradoxale</strong>.</li><li>Un <strong>balancement thoraco-abdominal</strong>.</li><li>Un <strong>épuisement</strong>.</li><li>Un <strong>silence auscultatoire</strong>.</li><li>La <strong>difficulté à s'alimenter/parler</strong> pour les plus grands, ou à téter pour les nourrissons.</li><li>Une <strong>fréquence respiratoire et cardiaque inadaptées</strong> à l'âge.</li></ul>"},{"i":"34bb251181c9","n":188,"o":"188-10","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les signes cliniques d'une exacerbation d'asthme grave chez l'adulte ne nécessitant pas une réanimation immédiate ?","a":"<p>Les signes d'une exacerbation d'asthme grave sans défaillance vitale immédiate chez l'adulte incluent :</p><ul><li>Une <strong>dyspnée importante</strong>.</li><li>L'impossibilité de prononcer une <strong>phrase complète</strong>.</li><li>Une fréquence respiratoire <strong>supérieure à 30 cycles/minute</strong>.</li><li>Une fréquence cardiaque <strong>supérieure à 120 battements/minute</strong>.</li><li>Un <strong>tirage sus-sternal ou intercostal</strong>.</li><li>Un <strong>sibilants</strong> audible à distance.</li></ul>"},{"i":"34dc86d89d46","n":188,"o":"188-10","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les signes cliniques de gravité immédiate chez un adulte présentant une exacerbation d'asthme ?","a":"<p>Chez l'adulte, les signes cliniques de gravité immédiate d'une exacerbation d'asthme incluent :</p><ul><li>Une <strong>bradycardie</strong> ou des <strong>troubles du rythme</strong>.</li><li>Une <strong>cyanose</strong>.</li><li>Des <strong>troubles de la conscience</strong> (agitation, confusion, sommeil).</li><li>Un <strong>épuisement respiratoire</strong> avec respiration paradoxale thoraco-abdominale.</li><li>Un <strong>silence auscultatoire</strong>.</li><li>Une <strong>hypotension artérielle</strong>.</li></ul>"},{"i":"6831cb808bd5","n":188,"o":"188-10","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les critères paracliniques d'un asthme aigu grave chez l'adulte ou l'enfant ?","a":"<p>Les critères paracliniques d'un asthme aigu grave incluent :</p><ul><li>Un <strong>débit expiratoire de pointe (DEP) inférieur à 50%</strong> de la meilleure valeur ou de la valeur théorique.</li><li>Une <strong>SpO2 inférieure à 90%</strong> en air ambiant.</li><li>Une <strong>PaO2 inférieure à 60 mmHg</strong> en air ambiant.</li><li>Une <strong>PaCO2 normale (35-45 mmHg) ou élevée (> 45 mmHg)</strong>, ce dernier signant un épuisement.</li><li>Un <strong>pH inférieur à 7,30</strong> (acidose respiratoire).</li></ul>"},{"i":"0fabb68a6f3d","n":188,"o":"188-14","u":"Etiologies","t":"Connaître les grandes étiologies professionnelles","q":"Quels sont les principaux agents responsables d'asthme professionnel à bas poids moléculaire (HPM) ?","a":"<p>Les agents à bas poids moléculaire (moins de 1000 Dalton) fréquemment impliqués dans l'asthme professionnel sont :</p><ul><li>Les <strong>isocyanates</strong> (peintures, mousses, adhésifs).</li><li>Les <strong>anhydrides acides</strong>.</li><li>Les <strong>persulfates</strong> (coiffeurs).</li><li>Les <strong>aldéhydes</strong> (formaldéhyde).</li><li>Certains métaux (<strong>chrome, nickel, platine</strong>).</li></ul>"},{"i":"1c65bb01d027","n":188,"o":"188-14","u":"Etiologies","t":"Connaître les grandes étiologies professionnelles","q":"Quels sont les principes généraux du diagnostic d'un asthme ou d'une rhinite professionnelle ?","a":"<p>Le diagnostic d'un asthme ou d'une rhinite professionnelle repose sur :</p><ul><li>Un lien entre les symptômes et l'exposition <strong>professionnelle</strong>.</li><li>L'identification de l'agent causal incriminé.</li><li>La mise en évidence d'une <strong>relation causale</strong> par des tests spécifiques (tests de provocation) ou par l'amélioration après éviction.</li></ul>"},{"i":"cf0e4539f365","n":188,"o":"188-14","u":"Etiologies","t":"Connaître les grandes étiologies professionnelles","q":"Quels sont les principaux agents responsables d'asthme professionnel à haut poids moléculaire (HPM) ?","a":"<p>Les agents à haut poids moléculaire (plus de 1000 Dalton) fréquemment impliqués dans l'asthme professionnel sont :</p><ul><li>Les <strong>farines</strong> et les enzymes (boulangerie).</li><li>Les <strong>acariens</strong> de stockage (agriculteurs).</li><li>Les <strong>animaux de laboratoire</strong> (protéines animales).</li><li>Les <strong>latex</strong> (professionnels de santé).</li><li>Les moisissures et les <strong>allergènes végétaux</strong> (scieries, horticulture).</li></ul>"},{"i":"f78dbbc12755","n":188,"o":"188-14","u":"Etiologies","t":"Connaître les grandes étiologies professionnelles","q":"Comment confirmer le diagnostic d'un asthme ou d'une rhinite professionnelle ?","a":"<p>La confirmation du diagnostic repose sur :</p><ul><li>L'amélioration des symptômes après <strong>éviction</strong> de l'agent.</li><li>La réapparition des symptômes à la <strong>réexposition</strong>.</li><li>Des tests diagnostiques spécifiques : <strong>Tests cutanés</strong> (prick tests), dosage d'<strong>IgE spécifiques</strong> si disponibles, ou <strong>tests de provocation bronchique ou nasale</strong> spécifiques en milieu spécialisé.</li></ul>"},{"i":"17057765fe3b","n":188,"o":"188-16","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la rhinite allergique","q":"Que constitue la première étape essentielle dans la prise en charge de toute rhinite allergique, indépendamment de sa sévérité ?","a":"<p>La première étape essentielle est l'<strong>éviction allergénique</strong>. Cela consiste à identifier et à réduire l'exposition à l'allergène déclencheur lorsque cela est possible (ex: acariens, poils d'animaux, pollens).</p>"},{"i":"a46b7ceb3d9b","n":188,"o":"188-16","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la rhinite allergique","q":"Quels sont les principes thérapeutiques de la rhinite allergique saisonnière intermittente, telle que définie par la classification ARIA (Allergic Rhinitis and its Impact on Asthma) ?","a":"<p>Pour la rhinite allergique saisonnière intermittente, les principes thérapeutiques reposent généralement sur :</p><ul><li>Les <strong>antihistaminiques H1 de deuxième génération</strong> par voie orale ou topique (nasale ou oculaire).</li><li>Les <strong>décongestionnants nasaux</strong> (alpha-mimétiques) de courte durée (maximum 5 jours) en cas d'obstruction nasale importante.</li></ul>"},{"i":"ed58e3426109","n":188,"o":"188-16","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la rhinite allergique","q":"Quels sont les principes thérapeutiques de la rhinite allergique persistante ou sévère (classification ARIA) ?","a":"<p>Pour la rhinite allergique persistante ou sévère, les principes thérapeutiques incluent :</p><ul><li>Les <strong>corticoïdes intranasaux</strong> (avec ou sans antihistaminiques H1). C'est le traitement de première intention.</li><li>Un <strong>antihistaminique H1 de deuxième génération</strong> par voie orale en complément si les symptômes sont non contrôlés.</li><li>Un <strong>antagoniste des récepteurs des leucotriènes</strong> peut être proposé en cas de rhinite allergique associée à un asthme.</li><li>L'<strong>immunothérapie allergénique</strong> (désensibilisation) peut être envisagée en cas d'échec des traitements pharmacologiques ou de formes sévères monosensibilisées.</li></ul>"},{"i":"adad5e486d25","n":188,"o":"188-17","u":"Prise en charge","t":"Connaître les grands principes thérapeutiques de fond de la maladie asthmatique avec les principales classes thérapeutiques utilisables","q":"Quels sont les principes généraux du traitement de fond de l'asthme bronchique ?","a":"<p>La prise en charge de fond de l'asthme vise à :</p><ul><li>Atteindre et maintenir le contrôle des symptômes.</li><li>Prévenir les exacerbations asthmatiques.</li><li>Maintenir une fonction respiratoire aussi normale que possible.</li><li>Éviter les effets indésirables liés au traitement.</li></ul>"},{"i":"eb022f0256b0","n":188,"o":"188-17","u":"Prise en charge","t":"Connaître les grands principes thérapeutiques de fond de la maladie asthmatique avec les principales classes thérapeutiques utilisables","q":"Quel est le rôle des corticostéroïdes inhalés (CSI) dans le traitement de fond de l'asthme ?","a":"<p>Les corticostéroïdes inhalés (CSI) sont le traitement de fond le plus efficace de l'asthme. Ils agissent en réduisant l'<strong>inflammation bronchique</strong> chronique, améliorant ainsi la fonction pulmonaire, diminuant la fréquence et la sévérité des symptômes, et prévenant les exacerbations asthmatiques.</p>"},{"i":"faac366f47e9","n":188,"o":"188-17","u":"Prise en charge","t":"Connaître les grands principes thérapeutiques de fond de la maladie asthmatique avec les principales classes thérapeutiques utilisables","q":"Quelles sont les principales classes thérapeutiques utilisées dans le traitement de fond de l'asthme persistant ?","a":"<p>Les classes thérapeutiques principales sont :</p><ul><li>Les <strong>corticostéroïdes inhalés</strong> (CSI), qui constituent la pierre angulaire du traitement de fond.</li><li>Les <strong>bêta-2 agonistes de longue durée d'action</strong> (LABA), toujours associés aux CSI.</li><li>Les <strong>antileucotriènes</strong> (montélukast).</li><li>Les <strong>anti-IgE</strong> (omalizumab) et autres biothérapies pour les asthmes sévères non contrôlés.</li></ul>"},{"i":"424e605e2e46","n":188,"o":"188-19","u":"Prise en charge","t":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l’asthme en première intention","q":"Comment doit être surveillée la compliance et la bonne utilisation des dispositifs d'inhalation du traitement de fond de l'asthme ?","a":"<p>La surveillance doit être effectuée à chaque consultation. Il est important de vérifier la <strong>technique d'inhalation</strong> du patient et d'évaluer sa <strong>bonne observance</strong> au traitement, car une mauvaise utilisation ou une faible adhérence sont des causes fréquentes d'échec thérapeutique.</p>"},{"i":"cff3c06db275","n":188,"o":"188-19","u":"Prise en charge","t":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l’asthme en première intention","q":"Quelle est la fréquence recommandée de la surveillance du traitement de fond de l'asthme en première intention ?","a":"<p>La fréquence de surveillance est initialement plus rapprochée (par exemple, <strong>1 à 3 mois</strong> après l'instauration ou l'ajustement du traitement), puis peut devenir <strong>annuelle</strong> une fois l'asthme bien contrôlé et stable.</p>"},{"i":"d418832f56d0","n":188,"o":"188-19","u":"Prise en charge","t":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l’asthme en première intention","q":"Quels sont les paramètres à évaluer lors de la surveillance de l'efficacité et de la tolérance du traitement de fond de l'asthme ?","a":"<ul><li><strong>Contrôle des symptômes</strong> : fréquence des symptômes diurnes et nocturnes, consommation de BDCA.</li><li><strong>Fonction respiratoire</strong> : mesure du <strong>VEMS</strong> (volume expiré maximal par seconde) et/ou du <strong>DEP</strong> (débit expiratoire de pointe).</li><li><strong>Fréquence et sévérité des exacerbations</strong> asthmatiques.</li><li><strong>Effets indésirables</strong> du traitement (locaux ou systémiques).</li><li><strong>Impact sur la qualité de vie</strong> du patient.</li></ul>"},{"i":"ff9b4159622a","n":188,"o":"188-19","u":"Prise en charge","t":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l’asthme en première intention","q":"Quels sont les objectifs principaux de la surveillance du traitement de fond de l'asthme en première intention ?","a":"<p>Les objectifs sont l'absence de symptômes diurnes ou nocturnes, l'absence d'exacerbations, une fonction pulmonaire normale ou optimale, l'absence de recours aux bronchodilatateurs de courte durée d'action (BDCA), et la prévention d'une limitation permanente du flux aérien.</p>"},{"i":"51e04bc5e019","n":188,"o":"188-20","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement d’urgence d’une crise d’asthme chez l’enfant et l’adulte","q":"Quelle est la voie d'administration privilégiée pour les bêta-2 mimétiques dans le traitement d'urgence d'une crise d'asthme ?","a":"<p>La voie d'administration privilégiée pour les bêta-2 mimétiques dans le traitement d'urgence d'une crise d'asthme est la <strong>voie inhalée</strong>, idéalement via un <strong>chambre d'inhalation</strong> ou un <strong>nébuliseur</strong>, adaptant le dispositif à l'âge et à la gravité.</p>"},{"i":"8198cb6d4013","n":188,"o":"188-20","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement d’urgence d’une crise d’asthme chez l’enfant et l’adulte","q":"Quel autre traitement systémique peut être associé aux bronchodilatateurs de courte durée d'action dans la prise en charge d'urgence d'une crise d'asthme modérée à sévère ?","a":"<p>En cas de crise d'asthme modérée à sévère, un traitement systémique par <strong>corticostéroïdes oraux</strong> ou <strong>intraveineux</strong> peut être associé aux bronchodilatateurs de courte durée d'action. Les corticostéroïdes agissent pour réduire l'inflammation bronchique.</p>"},{"i":"faf7ce6d5685","n":188,"o":"188-20","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement d’urgence d’une crise d’asthme chez l’enfant et l’adulte","q":"Comment initie-t-on le traitement d'urgence d'une crise d'asthme chez l'enfant et l'adulte, en première intention ?","a":"<p>Le traitement d'urgence de première intention d'une crise d'asthme chez l'enfant et l'adulte repose sur l'administration rapide de <strong>bronchodilatateurs de courte durée d'action</strong> (BDCA), principalement les <strong>bêta-2 mimétiques inhalés</strong>.</p>"},{"i":"04c04554ab3d","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Quelles sont les mesures d'éviction à prendre pour un patient allergique aux moisissures, notamment en cas d'asthme ?","a":"<p>Pour les moisissures, les mesures d'éviction visent à contrôler l'humidité :</p><ul><li>Ventiler régulièrement les pièces, surtout les salles de bain et cuisines.</li><li>Réparer toute <strong>fuite d'eau</strong> ou infiltration.</li><li>Nettoyer les moisissures visibles avec des produits adaptés (eau de Javel diluée, vinaigre blanc).</li><li>Utiliser un <strong>déshumidificateur</strong> si nécessaire.</li><li>Éviter les plantes d'intérieur en grande quantité et les tas de feuilles mortes à proximité du domicile.</li></ul>"},{"i":"5ca0dc83fcaa","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Quelles sont les principales mesures d'éviction des pollens à recommander aux patients souffrant de rhinite allergique ou d'asthme pollinique ?","a":"<p>Pour les pollens, les mesures d'éviction incluent :</p><ul><li>Consulter les <strong>bulletins polliniques</strong> et éviter les sorties en période de pic.</li><li>Garder les fenêtres de la maison et de la voiture <strong>fermées</strong>, surtout en fin de matinée et en début d'après-midi, et lors de vent.</li><li>Éviter les activités extérieures (jardinage, tonte) qui exposent directement aux pollens.</li><li>Porter des <strong>lunettes de soleil</strong> à l'extérieur pour protéger les yeux.</li><li>Se laver les cheveux et changer de vêtements après toute activité extérieure prolongée.</li></ul>"},{"i":"8ab249cb43b3","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Quelles sont les principales mesures d'éviction des acariens à recommander aux patients asthmatiques ou ayant une rhinite allergique ?","a":"<p>Pour les acariens, les mesures d'éviction incluent :</p><ul><li>Utiliser des <strong>housses anti-acariens</strong> sur la literie (matelas, oreillers, couettes).</li><li>Laver la literie (draps, taies) chaque semaine à <strong>60°C</strong>.</li><li>Maintenir une <strong>température ambiante basse</strong> (idéalement inférieure à 20°C) et une <strong>faible humidité</strong> (inférieure à 50%) dans la chambre.</li><li>Retirer les moquettes, tapis, rideaux épais et peluches de la chambre, ou les laver fréquemment.</li><li>Aérer quotidiennement la chambre.</li><li>Nettoyer le sol avec un aspirateur muni d'un <strong>filtre HEPA</strong>.</li></ul>"},{"i":"92964fb7455b","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Comment conseiller un patient asthmatique ou allergique face à une allergie aux animaux domestiques ?","a":"<p>En cas d'allergie aux animaux, la mesure la plus efficace est l'<strong>éviction totale de l'animal</strong> du domicile. Si ce n'est pas possible :</p><ul><li>Empêcher l'animal d'entrer dans la <strong>chambre</strong> du patient.</li><li>Laver l'animal <strong>fréquemment</strong> (1 à 2 fois par semaine) pour réduire la charge allergénique.</li><li>Utiliser un aspirateur avec <strong>filtre HEPA</strong> et nettoyer régulièrement les surfaces.</li><li>Éviter les tapis et les moquettes qui retiennent les allergènes.</li><li>Se laver les mains après contact avec l'animal.</li></ul>"},{"i":"e3fad1662212","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Quels sont les principes généraux des mesures d'éviction allergénique à conseiller aux patients souffrant d'asthme ou de rhinite allergique ?","a":"<p>Les principes généraux incluent :</p><ul><li>Identifier le ou les <strong>allergènes responsables</strong> (tests cutanés, IgE spécifiques).</li><li>Réduire l'exposition à ces allergènes dans l'<strong>environnement quotidien</strong> du patient (domicile, travail, école).</li><li>Adapter les mesures en fonction de la <strong>nature de l'allergène</strong> (acariens, pollens, moisissures, poils d'animaux, allergènes professionnels).</li><li>Éduquer le patient sur l'importance de la <strong>régularité</strong> et de la <strong>persistance</strong> des mesures.</li></ul>"},{"i":"f398bb16bbee","n":188,"o":"188-22","u":"Prise en charge","t":"Connaître les principales mesures d’éviction allergénique dans l’asthme et la rhinite allergique, y compris professionnels","q":"Quelles sont les principales mesures d'éviction pour les patients atteints d'asthme ou de rhinite allergique professionnelle ?","a":"<p>Pour les allergies professionnelles, la mesure la plus importante est l'<strong>identification et l'éviction de l'allergène sur le lieu de travail</strong>.</p><ul><li>Si l'éviction de l'allergène au poste de travail est impossible, un <strong>changement de poste</strong> ou une <strong>reconversion professionnelle</strong> peut être nécessaire.</li><li>Utiliser des <strong>équipements de protection individuelle (EPI)</strong> adaptés (masques filtrants, gants).</li><li>Améliorer la <strong>ventilation</strong> et l'<strong>aspiration à la source</strong> des contaminants.</li><li>Informer la <strong>médecine du travail</strong> pour une prise en charge adaptée et la déclaration en maladie professionnelle si nécessaire.</li></ul>"},{"i":"0b34e82a6b19","n":188,"o":"188-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’une rhinite allergique chez l’enfant et l’adulte","q":"Quels sont les principaux diagnostics différentiels de la rhinite allergique chez l'enfant et l'adulte ?","a":"<p>Les principaux diagnostics différentiels à considérer sont :</p><ul><li>La <strong>rhinite infectieuse</strong> (virale ou bactérienne)</li><li>La <strong>rhinite non allergique non infectieuse</strong> (rhinite vasomotrice, rhinite médicamenteuse, rhinite hormonale, rhinite gustative)</li><li>La <strong>présence de corps étrangers</strong> chez l'enfant</li><li>Les <strong>malformations anatomiques</strong> (déviation septale majeure, hypertrophie des cornets)</li><li>La <strong>polypose nasale</strong></li><li>La <strong>rhinorrhée de liquide cérébrospinal</strong> (rare, post-traumatique ou chirurgicale)</li></ul>"},{"i":"2a446e3c5327","n":188,"o":"188-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’une rhinite allergique chez l’enfant et l’adulte","q":"Quels examens complémentaires sont utiles pour confirmer le diagnostic de rhinite allergique et identifier l'allergène causal chez l'enfant et l'adulte ?","a":"<p>Les examens complémentaires incluent :</p><ul><li>Les <strong>tests cutanés d'allergie</strong> (prick tests), qui sont l'examen de première intention pour rechercher une sensibilisation IgE-médiatisée.</li><li>Le dosage des <strong>IgE spécifiques</strong> dans le sérum (par exemple, RAST ou ImmunoCAP), utile si les tests cutanés sont impossibles ou discordants.</li><li>L'<strong>endoscopie nasale</strong> peut être réalisée pour éliminer d'autres causes d'obstruction nasale ou de rhinorrhée.</li></ul>"},{"i":"d5bd61e6022a","n":188,"o":"188-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’une rhinite allergique chez l’enfant et l’adulte","q":"Comment définit-on cliniquement la rhinite allergique chez l'enfant et l'adulte ?","a":"<p>La rhinite allergique se caractérise par l'association d'au moins deux des symptômes suivants :</p><ul><li><strong>Éternuements</strong> répétés et en salves</li><li><strong>Prurit nasal</strong> (démangeaisons)</li><li><strong>Rhinorrhée antérieure claire</strong> (écoulement nasal)</li><li><strong>Obstruction nasale</strong> (nez bouché)</li></ul><p>Ces symptômes surviennent pendant <strong>plus d'une heure par jour</strong> et <strong>plusieurs jours par semaine</strong>.</p>"},{"i":"fc1cad17d676","n":188,"o":"188-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’une rhinite allergique chez l’enfant et l’adulte","q":"Quels sont les éléments clés de l'interrogatoire pour le diagnostic positif d'une rhinite allergique chez l'enfant et l'adulte ?","a":"<p>L'interrogatoire doit préciser :</p><ul><li>Le <strong>caractère saisonnier ou perannuel</strong> des symptômes</li><li>La <strong>présence de facteurs déclenchants</strong> (exposition à des allergènes comme les pollens, acariens, poils d'animaux)</li><li>L'<strong>horaire de survenue</strong> des symptômes (matin, nuit)</li><li>L'<strong>impact sur la qualité de vie</strong> (sommeil, concentration)</li><li>Les <strong>antécédents personnels et familiaux d'atopie</strong> (asthme, eczéma, autres allergies)</li><li>L'<strong>efficacité des traitements symptomatiques</strong> (antihistaminiques, corticoïdes nasaux)</li></ul>"},{"i":"222c52d7647e","n":188,"o":"188-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","q":"Quels sont les éléments clés du diagnostic positif de l'asthme chez l'adulte et l'enfant ?","a":"<p>Le diagnostic positif de l'asthme repose sur la présence de <strong>symptômes respiratoires variables</strong> (sibilants, dyspnée, toux, oppression thoracique) et la mise en évidence d'une <strong>obstruction bronchique réversible</strong>.</p>"},{"i":"4c3dd87c1d33","n":188,"o":"188-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","q":"Comment caractériser les symptômes de l'asthme ?","a":"<ul><li>Les symptômes sont <strong>variables dans le temps et en intensité</strong>.</li><li>Ils sont souvent déclenchés par des <strong>facteurs spécifiques</strong> (allergènes, exercice, air froid, infections virales).</li><li>Ils prédominent la <strong>nuit ou au petit matin</strong>.</li><li>Ils répondent généralement aux <strong>bronchodilatateurs</strong>.</li></ul>"},{"i":"7ba43a4c7bea","n":188,"o":"188-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","q":"Quels sont les diagnostics différentiels majeurs de l'asthme chez l'adulte ?","a":"<ul><li><strong>BPCO</strong> (orientation tabagique, âge > 40 ans, obstruction peu réversible).</li><li><strong>Insuffisance cardiaque gauche</strong> (dyspnée d'effort, orthopnée, crépitants pulmonaires).</li><li><strong>Dysfonction des cordes vocales</strong> (stridor inspiratoire, absence de sibilants à l'auscultation, spirométrie atypique).</li><li>Causes bronchiques rares : <strong>dilatation des bronches, corps étranger endobronchique</strong>.</li></ul>"},{"i":"c4f49e9784b0","n":188,"o":"188-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","q":"Quel est l'examen fonctionnel respiratoire clé pour le diagnostic de l'asthme et que doit-il mettre en évidence ?","a":"<p>L'examen clé est la <strong>spirométrie</strong>. Elle doit objectiver un <strong>syndrome obstructif</strong> (VEMS/CVF < 0,7 après bronchodilatateur) et une <strong>réversibilité significative</strong> de cette obstruction (augmentation du VEMS de <strong>plus de 12% et d'au moins 200 mL</strong> après bronchodilatateur).</p>"},{"i":"fbc7313259db","n":188,"o":"188-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d’un asthme chez l’enfant et l’adulte","q":"Quels sont les diagnostics différentiels principaux de l'asthme chez l'enfant ?","a":"<ul><li><strong>Bronchiolite virale récidivante</strong> (notamment chez le jeune enfant, sibilants en contexte infectieux).</li><li><strong>Corps étranger intrabronchique</strong> (notamment en cas de début brutal avec toux, dyspnée).</li><li><strong>Mucoviscidose</strong> (retard de croissance, troubles digestifs, infections respiratoires à répétition).</li><li><strong>Reflux gastro-œsophagien</strong> (toux chronique, régurgitations).</li><li><strong>Dyskinésie ciliaire primitive</strong> (sinusites, otites, bronchectasies).</li></ul>"},{"i":"68bd9c022c50","n":188,"o":"188-8","u":"Diagnostic positif","t":"Connaître les modalités d’évaluation du contrôle de l’asthme","q":"Quels sont les principaux critères cliniques utilisés pour juger d'un bon contrôle de l'asthme ?","a":"<ul><li><strong>Symptômes diurnes</strong> : rares (moins de 2 fois par semaine).</li><li><strong>Symptômes nocturnes/réveils nocturnes</strong> : absents.</li><li><strong>Besoins en bronchodilatateurs de secours</strong> : faibles (moins de 2 fois par semaine).</li><li><strong>Limitations des activités physiques</strong> : absentes.</li></ul>"},{"i":"c0f1d61a0b1c","n":188,"o":"188-8","u":"Diagnostic positif","t":"Connaître les modalités d’évaluation du contrôle de l’asthme","q":"Quel est le rôle de la fonction respiratoire dans l'évaluation du contrôle de l'asthme ?","a":"<p>La fonction respiratoire, évaluée par le <strong>VEMS</strong> (Volume Expiratoire Maximum par Seconde) ou le <strong>DEP</strong> (Débit Expiratoire de Pointe), doit être <strong>normale ou très proche de la normale</strong>, ou correspondre au meilleur score du patient. Une fonction respiratoire altérée malgré des symptômes contrôlés peut indiquer un asthme non contrôlé sur le plan inflammatoire.</p>"},{"i":"f08b58158b60","n":188,"o":"188-8","u":"Diagnostic positif","t":"Connaître les modalités d’évaluation du contrôle de l’asthme","q":"Comment évalue-t-on le contrôle de l'asthme chez un patient ?","a":"<p>L'évaluation du contrôle de l'asthme repose sur l'analyse de plusieurs critères cliniques et fonctionnels respiratoires sur une période donnée (généralement les <strong>4 dernières semaines</strong>).</p>"},{"i":"635b7b9ada76","n":188,"o":"188-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les éléments clés à rechercher à l'examen clinique pour évaluer la sévérité d'une exacerbation d'asthme chez l'enfant et l'adulte ?","a":"<ul><li><strong>Niveau d'éveil</strong> et discours (phrases complètes, mots)</li><li><strong>Fréquence respiratoire</strong> et cardiaque</li><li>Présence de <strong>signes de lutte respiratoire</strong> (tirage, battement des ailes du nez, balancement thoraco-abdominal chez l'enfant)</li><li><strong>Sibilants</strong> (leur absence peut parfois traduire un trouble ventilatoire majeur)</li><li><strong>Cyanose</strong></li><li>Mesure du <strong>débit expiratoire de pointe (DEP)</strong> ou du VEMS si possible</li></ul>"},{"i":"dbc751ae661d","n":188,"o":"188-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les principaux critères cliniques permettant de poser le diagnostic d'exacerbation d'asthme chez l'enfant et l'adulte ?","a":"<p>Le diagnostic d'exacerbation d'asthme repose principalement sur l'aggravation rapide de la dyspnée, de la toux et de la sibilance. On observe également une sensation d'oppression thoracique et une diminution de la tolérance à l'effort.</p>"},{"i":"ed425a66af33","n":188,"o":"188-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’exacerbation d’asthme chez l’enfant et l’adulte","q":"Quels sont les signes d'alerte ou de gravité d'une exacerbation d'asthme chez l'enfant et l'adulte, nécessitant une prise en charge urgente ?","a":"<ul><li><strong>Dyspnée majeure</strong> et incapacité à parler (phrases courtes ou mots isolés)</li><li><strong>Cyanose</strong> des lèvres ou des extrémités</li><li><strong>Détresse respiratoire</strong> importante avec signes de lutte marqués</li><li><strong>Bradycardie</strong> ou arythmie</li><li><strong>Confusion</strong> ou agitation</li><li><strong>Silencieux auscultatoire</strong> (absence de sibilants) après des sibilants intenses, suggérant une obstruction très sévère</li><li><strong>Inefficacité des bronchodilatateurs</strong> de courte durée d'action inhalés</li></ul>"},{"i":"fe5fcafad780","n":188,"o":"188-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’exacerbation d’asthme chez l’enfant et l’adulte","q":"Quel est l'intérêt de la mesure du débit expiratoire de pointe (DEP) ou du VEMS dans le diagnostic et le suivi d'une exacerbation d'asthme chez l'adulte et l'enfant coopérant ?","a":"<p>La mesure du <strong>Débit Expiratoire de Pointe (DEP)</strong> ou du <strong>VEMS</strong> (Volume Expiratoire Maximal par Seconde) permet de quantifier objectivement l'obstruction bronchique et de suivre son évolution. C'est un indicateur clé de la <strong>sévérité de l'exacerbation</strong> et de la réponse au traitement.</p>"}]};